insert into public.content (collection, slug, data, status) values
('briefs', 'gendering-the-green-transition', $rita${"title":"Gendering the green transition","number":4,"programme":"IND","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Shingie Chisoro"],"basedOn":["gendering-structural-change-and-green-transition-in-africa-implications","gendering-green-transition-in-africa-implications-of-transformative"],"date":"2024-10","recommendations":[{"text":"Put gender at the centre of industrial policy with a gender-transformative industrial policy framework (G-TRIP).","why":"Structural change in Africa has tended to widen gender employment gaps."},{"text":"Expand women’s economic opportunities and social standing alongside industrial and green policy.","why":"Countries with such policies offset the negative effect of structural change on gender balance."},{"text":"Open green energy and transition-technology jobs to women by tackling the inequalities that keep them out.","why":"These sectors offer gender-balanced employment, but entrenched inequalities stand in the way."}],"issue":"Africa’s structural transformation and green transition are reshaping who works where. Without deliberate policy, the shift risks leaving women behind.","evidence":"Panel data for 48 African countries from 1992 to 2019 show that shifts in sectoral composition have tended to worsen gender employment balance. Policies that expand women’s economic opportunities offset this effect.\n\nCase studies of Ghana and South Africa show that green energy systems and transition technologies create room for more gender-balanced employment, but entrenched gender inequalities are a major obstacle.","pdf":"https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","sources":["https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","https://cris.maastrichtuniversity.nl/en/publications/gendering-green-transition-in-africa-implications-of-transformati/","https://econpapers.repec.org/RePEc:unm:unumer:2026011","https://www.wits.ac.za/events-archive/scis/gendering-structural-change-and-green-transition-in-africa-implications-of-transformative-policies.php"]}$rita$::jsonb, 'published'),
('briefs', 'gvcs-job-creation-and-job-destruction', $rita${"title":"GVCs, job creation and job destruction","number":6,"programme":"INN","authors":["Gideon Ndubuisi","Solomon Owusu"],"basedOn":["opeds:global-value-chains-job-creation-and-job-destruction-among-firms-in","global-value-chains-job-creation-and-job-destruction-among-firms-in"],"date":"2026-03","recommendations":[{"text":"Help new, small and young firms enter global value chains.","why":"Net job gains from GVC integration are driven by firms entering GVCs, largely younger and smaller ones."},{"text":"Pair GVC promotion with support for workers in firms that already trade in GVCs.","why":"Continuing GVC firms show an overall net job loss, so the job effects are uneven."},{"text":"Judge GVC policy on jobs as well as productivity.","why":"The full welfare effect of GVC trade depends on both productivity gains and net job reallocation."}],"issue":"Global value chains can raise productivity, but the technologies they bring may save labour. For South Africa, with very high unemployment, the question is whether GVC integration creates jobs or leads to jobless growth.","evidence":"Using administrative data on the universe of formal manufacturing firms from the South African Revenue Service and National Treasury, the study finds that GVC integration is linked to net job gains at the firm level, through job reallocation. The gains are driven by firms entering GVCs, largely younger and smaller firms. Firms that continuously participate in GVCs show an overall net job loss.","pdf":"https://steg.cepr.org/sites/default/files/2023-08/WP073%20NdubuisiOwusuGlobalValueChainsJobCreation.pdf","sources":["https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","https://cepr.org/publications/wp073","https://grp.cepr.org/steg/projects/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa"]}$rita$::jsonb, 'published'),
('briefs', 'keeping-industry-running-electricity-crises-and-south-african', $rita${"title":"Keeping industry running: electricity crises and South African manufacturing","number":2,"programme":"EN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Rex Asiama"],"basedOn":["jobs-investments-and-exporting-the-real-effects-of-electricity-crises","dancing-on-the-grid-electricity-crises-manufacturing-energy"],"date":"2026","recommendations":[{"text":"Treat reliable electricity as productive infrastructure for industry, not only as a utility service.","why":"Outages destroyed jobs, lowered capital investment and disrupted exports of manufacturing firms."},{"text":"Target support at the most energy-vulnerable manufacturing sub-sectors.","why":"Job losses were largest in sectors with higher energy vulnerability, in both formal and informal work."},{"text":"Rebuild lost capabilities, not just lost power, in South Africa’s green transition.","why":"Restoring supply does not restore the skills, investment and export links that firms lost during the crises."}],"issue":"Since 2007, South Africa’s electricity crises have disrupted production across manufacturing. Repeated outages make it costlier to keep workers, delay investment and push firms into expensive backup power. Power has now returned, but the damage to industry remains.","evidence":"Using South Africa’s input–output matrices, the authors build an index of manufacturing sub-sector energy vulnerability. It shows large differences across sub-sectors. Electricity crises are linked to significant job losses, and the damage is greatest in the most energy-vulnerable sectors, for formal and informal jobs alike.\n\nFirm-level evidence shows the crises also lowered capital investment and upended export activity. Ownership structure, firm age, size and financial status shape how hard firms are hit.","pdf":"https://repository.tudelft.nl/file/File_2c5d23b2-81b6-465e-b966-0b0696134767","sources":["https://doi.org/10.1016/j.eneco.2026.109234","https://doi.org/10.1016/j.enpol.2025.114534","https://ideas.repec.org/p/unu/wpaper/wp-2024-41.html","https://sa-tied.wider.unu.edu/article/jobs-investments-and-exporting-the-real-effects-of-electricity-crises-in-south-africa","https://africanarguments.org/?p=48463"]}$rita$::jsonb, 'published'),
('briefs', 'no-chips-no-power-africa-and-the-semiconductor-value-chain', $rita${"title":"No chips, no power: Africa and the semiconductor value chain","number":5,"programme":"INN","authors":["Gideon Ndubuisi"],"basedOn":["opeds:no-chips-no-power-why-africa-must-enter-the-global-semiconductor-value"],"date":"2026-02","recommendations":[{"text":"Enter the semiconductor value chain through feasible segments: chip design, assembly, testing and packaging, and power electronics.","why":"Fabrication needs capital, infrastructure and reliable energy that Africa lacks today; these segments need far less."},{"text":"Enter collectively, using the AfCFTA.","why":"No single African market is large enough on its own."},{"text":"Link Africa’s critical minerals to chip-related production rather than exporting them raw.","why":"Africa holds a large share of the minerals used in chips but contributes less than 1% of global semiconductor output."}],"issue":"Chips run everything from cars to clinics to the power grid. Africa supplies many of the critical minerals used to make them, but accounts for less than 1% of global semiconductor output.","evidence":"Fabrication is highly capital-intensive and needs advanced infrastructure, industrial water and reliable power. Chip design does not require a fabrication plant, and assembly, testing and packaging need much lower investment. Countries such as Morocco, Nigeria, Kenya and Rwanda are already moving into these segments.","pdf":"https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","sources":["https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","https://aasciences.africa/news/africa-semiconductor-forum-sets-path-from-minerals-to-microchips","https://www.weforum.org/stories/supply-chains-and-transportation/african-nations-hubs-global-semiconductor-supply-chain/","https://www.ecofinagency.com/news-industry/0609-58657-semiconductors-mapping-africa-s-capabilities-across-the-value-chain"]}$rita$::jsonb, 'published'),
('briefs', 'regional-mineral-value-chains-why-africa-must-coordinate', $rita${"title":"Regional mineral value chains: why Africa must coordinate","number":1,"programme":"MIN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo","Solomon Owusu","Woubet Kassa"],"basedOn":["regionalizing-green-transition-minerals-for-structural-transformation","opeds:africas-mineral-strength-is-wasted-if-countries-dont-work-together"],"date":"2025-10","recommendations":[{"text":"Pool mineral supplies, infrastructure and skills across borders.","why":"Small national volumes make it hard for any one country to influence buyers or attract large processing plants; pooling lowers costs and strengthens negotiating power."},{"text":"Make processing, technology transfer and worker training part of every mineral partnership.","why":"Partnerships with foreign governments and companies should go beyond extracting and exporting minerals."},{"text":"Use the AfCFTA to build intra-African mineral value chains, backed by shared infrastructure and harmonised standards.","why":"No single country holds every input; regional coordination turns geology into value chains."}],"issue":"Africa has deposits, reserves or production of at least one transition mineral in 48 countries, yet it exports most of them raw. Limited local processing, weak industrialisation and heavy dependence on Asian buyers, especially China, mean the continent captures little of the value its minerals create.","evidence":"The World Bank–commissioned study maps 41 minerals used in bioenergy, electricity networks, batteries, energy storage, electric vehicles and carbon capture. South Africa alone holds 24 of them. Local refining raises value sharply: Congolese cobalt sells for about US$5.80 per kilogram at extraction and US$16.20 after local refining.\n\nThe study reviews national and regional mineral and industrial policies and finds them fragmented. It concludes that only deeper regional cooperation, shared infrastructure and coordinated policy can turn mineral wealth into broad-based prosperity.","pdf":"https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","sources":["https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","https://www.downtoearth.org.in/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report","https://www.moneyweb.co.za/news/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report/"]}$rita$::jsonb, 'published'),
('briefs', 'solar-pv-manufacturing-in-africa-opportunity-or-mirage', $rita${"title":"Solar PV manufacturing in Africa: opportunity or mirage?","number":3,"programme":"EN","authors":["Gideon Ndubuisi","Elvis Korku Avenyo"],"basedOn":["solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage"],"date":"2024-07","recommendations":[{"text":"Adopt a regionalised solar PV strategy for Africa.","why":"Without a coordinated approach, individual countries are unlikely to integrate into the global solar market."},{"text":"Consolidate the continent’s minerals, technological capacities and investment into one integrated PV value chain across countries.","why":"Most countries lack the finance, technology and infrastructure to build a competitive sector alone."},{"text":"Divide the chain by strength: mineral-rich countries such as the DRC and Zambia focus on extraction and processing, others on later stages.","why":"Each African country exports at least one key solar raw material, mostly unprocessed."}],"issue":"Africa holds key minerals for solar PV, such as copper, tin and silicon, but most countries on their own lack the finance, technological capabilities and infrastructure to build a competitive PV manufacturing sector. China dominates nearly every segment of the global chain.","evidence":"Analysing critical minerals, trade and investment flows, the paper finds only limited and scattered opportunities for local solar PV manufacturing within individual African countries. Diversifying into the global chain is hard given market concentration, high entry barriers and established players. The paper concludes that a regional strategy is the realistic route in.","pdf":"https://afripoli.org/view-pdf/26/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","sources":["https://afripoli.org/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","https://www.pv-magazine.com/2024/10/10/africa-needs-regional-strategy-for-pv-manufacturing/","https://www.greenbuildingafrica.co.za/regionalised-solar-pv-manufacturing-strategy-required-to-integrate-into-the-global-solar-value-chain/"],"notes":""}$rita$::jsonb, 'published'),
