('insights', 'no-40-africas-green-industrialization-requires-learning-states', $rita${"number":40,"title":"Africa’s green industrialization requires learning states","programme":"IND","series":"Learning economy","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Learning economy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-41-forget-teslas-africas-ev-boom-is-happening-elsewhere-but-we', $rita${"number":41,"title":"Forget Teslas: Africa’s EV boom is happening elsewhere, but we have a problem","programme":"EN","series":"EVs","year":2026,"authors":["gideon-ndubuisi"],"topics":["EVs"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-42-industrial-ambition-without-institutional-transformation', $rita${"number":42,"title":"Industrial ambition without institutional transformation: Africa’s industrial policy challenge","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-43-productive-vs-distributive-coalitions-reimagining-africas', $rita${"number":43,"title":"Productive vs distributive coalitions: reimagining Africa’s industrial policy architecture","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-44-africas-industrial-window-of-opportunity-why-strategic', $rita${"number":44,"title":"Africa’s industrial window of opportunity: why strategic timing matters","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-45-the-missing-variable-in-africas-industrial-policy-debate', $rita${"number":45,"title":"The missing variable in Africa’s industrial policy debate: political settlements","programme":"IND","series":"Industrial policy architecture","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-5-why-africa-must-enter-the-green-industrialization-race-now', $rita${"number":5,"title":"Why Africa must enter the green industrialization race now","programme":"IND","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-6-africas-green-hydrogen-future-are-we-on-the-right-path', $rita${"number":6,"title":"Africa’s green hydrogen future: are we on the right path?","programme":"EN","year":2026,"authors":["gideon-ndubuisi"],"topics":["Green hydrogen"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-7-connecting-minerals-to-meals-africas-missed-agricultural', $rita${"number":7,"title":"Connecting minerals to meals: Africa’s missed agricultural link","programme":"MIN","year":2026,"authors":["gideon-ndubuisi"],"topics":["Minerals"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-8-waiting-for-solidarity-wont-work-why-africa-must-lead-in', $rita${"number":8,"title":"Waiting for solidarity won’t work: why Africa must lead in financing its own green industrial future","programme":"IND","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy","Finance"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('insights', 'no-9-africas-green-industrialization-blind-spot-who-will-buy', $rita${"number":9,"title":"Africa’s green industrialization blind spot: who will buy?","programme":"IND","series":"Blind spots","year":2026,"authors":["gideon-ndubuisi"],"topics":["Industrial policy"],"originalUrl":"https://sites.google.com/view/gideonndubuisi/policy-insights"}$rita$::jsonb, 'published'),
('jobs', 'call-for-contributions-policy-insights', $rita${"title":"Call for contributions, Policy Insights","jobType":"Call for contributions","location":"Remote","deadline":"Rolling","summary":"Pitch or submit a Policy Insight: one idea in 600–900 words on Africa’s green industrialisation.","applyUrl":"/submit","reportsTo":"Editor, Policy Insights"}$rita$::jsonb, 'published'),
('opeds', 'africas-mineral-strength-is-wasted-if-countries-dont-work-together', $rita${"title":"Africa’s mineral strength is wasted if countries don’t work together – new report","outlet":"The Conversation","date":"2026-09","authors":["Ndubuisi","Avenyo","Owusu","Kassa"],"kind":"research-blog","programme":"MIN","outletUrl":"https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","summary":"Transition minerals are found in 48 African countries, but most still export them raw and capture little value. Drawing on a World Bank–commissioned study, the authors argue that only regional cooperation, shared infrastructure and coordinated policy can turn mineral wealth into regional value chains.","keyPoints":["Most individual countries hold small global shares of each mineral, which weakens their bargaining power alone.","Local refining adds value: Congolese cobalt roughly triples in price after refining.","Pooled trade policy, shared processing centres and partnerships with local processing and skills transfer are proposed."],"sources":["https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306","https://www.downtoearth.org.in/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report"]}$rita$::jsonb, 'published'),
('opeds', 'awakening-industrial-economic-recovery-in-south-africa', $rita${"title":"Awakening industrial economic recovery in South Africa","outlet":"CCRED-IDTT Policy Brief","date":"2021-07","authors":["Avenyo","Bell","Nyamwena","Robb"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.competition.org.za/s/IDTT4_PB_Awakening_industrial_economic_recovery_in_South_Africa_202107.pdf","summary":"A policy brief from the Industrial Development Think Tank on reviving South Africa’s industrial economy after the COVID-19 shock.","sources":["https://www.competition.org.za/s/IDTT4_PB_Awakening_industrial_economic_recovery_in_South_Africa_202107.pdf","https://www.competition.org.za/idtt-year-4"]}$rita$::jsonb, 'published'),
('opeds', 'beyond-load-shedding-how-south-africas-electricity-crisis-scarred', $rita${"title":"Beyond load shedding: how South Africa’s electricity crisis scarred industry and deepened deindustrialisation","outlet":"African Arguments","date":"2026-10","authors":["Ndubuisi","Avenyo"],"kind":"research-blog","programme":"EN","summary":"Load shedding has ended, but the damage to manufacturing has not. Drawing on two studies in Energy Policy and Energy Economics, the authors show that outages cut jobs, postponed investment and cost export opportunities, and argue that restoring power does not restore lost capabilities.","outletUrl":"https://africanarguments.org/?p=48463","keyPoints":["Firms cut jobs, delayed investment, bought costly backup power and lost export opportunities.","Repeated interruptions broke the continuity manufacturing employment depends on.","Ending load shedding is only the beginning: electricity must be treated as productive infrastructure."],"sources":["https://africanarguments.org/?p=48463"]}$rita$::jsonb, 'published'),
('opeds', 'catastrophic-effects-of-covid-19-health-expenditure-shocks-and-poverty', $rita${"title":"Catastrophic effects of COVID-19 health expenditure shocks and multidimensional poverty in Ghana: what financing mechanisms mattered?","outlet":"AERC Policy Brief AHCV-PB-007","date":"2023-11","authors":["Ayanore","Avenyo","Osei"],"kind":"policy-brief","outletUrl":"https://publication.aercafricalibrary.org/handle/123456789/3696","summary":"More than half of Ghanaian households in the sample spent over 5% of their total expenditure on COVID-19-related health costs. Multidimensional poverty made these catastrophic payments worse, while insurance, remittances and government assistance softened the shock.","keyPoints":["52.2% of households spent more than 5% of total expenditure on COVID-19-related health costs.","Multidimensional poverty exacerbated catastrophic payments during the pandemic.","Insurance, remittances and government assistance mitigated the effects."],"sources":["https://publication.aercafricalibrary.org/handle/123456789/3696"]}$rita$::jsonb, 'published'),
('opeds', 'chinese-investment-in-africa-a-double-edged-sword-for-low-carbon', $rita${"title":"Chinese investment in Africa: a double-edged sword for low-carbon industrialisation","outlet":"BU Global Development Policy Center","date":"2024-07","authors":["Owusu","Tang","Ndubuisi"],"kind":"research-blog","programme":"IND","outletUrl":"https://www.bu.edu/gdp/2024/07/28/chinese-investment-in-africa-a-double-edged-sword-for-low-carbon-industrialization/","summary":"Chinese greenfield manufacturing investment raised industrial carbon emissions in Africa, especially when it went into labour- and resource-intensive manufacturing; the same effect does not appear for OECD investment. The authors argue for reshaping Chinese FDI, not discouraging it.","keyPoints":["Chinese FDI raised industrial emissions in 34 African countries (2003–2014).","The effect is strongest in labour- and resource-intensive manufacturing.","No such increase is found for FDI from OECD countries."],"sources":["https://www.bu.edu/gdp/2024/07/28/chinese-investment-in-africa-a-double-edged-sword-for-low-carbon-industrialization/"]}$rita$::jsonb, 'published'),
('opeds', 'climate-change-mitigation-for-late-industrialisers-technology-intensity', $rita${"title":"Climate change mitigation for late industrialisers: technology intensity in manufacturing","outlet":"SARChI Industrial Development Policy Brief 2023-01 (with CBDS, Copenhagen Business School)","date":"2023-02","authors":["Avenyo","Tregenna"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-01-avenyo-e--tregenna-f--january-2023.pdf","summary":"Late industrialisers need manufacturing to grow, but heavy industrialisation can raise emissions. Drawing on evidence from 56 developing economies, the brief asks whether greener industrial policy, shifting towards higher-technology manufacturing, lets countries industrialise while limiting emissions.","sources":["https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-01-avenyo-e--tregenna-f--january-2023.pdf","https://research-api.cbs.dk/ws/portalfiles/portal/89602649/elvis_korku_avenyo_et_al_climate_change_mitigation_for_late_industrialisers_publishersversion.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'digital-industrialisation-of-freshness', $rita${"title":"Digital industrialisation of freshness","outlet":"CCRED-IDTT Policy Brief 2022/09","date":"2022-09","authors":["Chisoro-Dube","Avenyo"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT5-PB9-Digital-Industrilisation-of-freshness_Final_06072022.pdf","summary":"A policy brief on how digital technologies are changing fresh-produce value chains in South Africa, part of the Industrial Development Think Tank’s series on climate change and green industrialisation.","sources":["https://www.competition.org.za/s/IDTT5-PB9-Digital-Industrilisation-of-freshness_Final_06072022.pdf","https://www.competition.org.za/idtt-year-5"]}$rita$::jsonb, 'published'),
('opeds', 'digital-technology-adoption-and-performance-in-south-african', $rita${"title":"Digital technology adoption and performance in South African manufacturing firms: early evidence for policy","outlet":"AERC Policy Brief","date":"2022-03","authors":["Avenyo","Bell"],"kind":"policy-brief","programme":"INN","outletUrl":"https://publication.aercafricalibrary.org/handle/123456789/3404","summary":"South Africa is a technological follower, and the recovery of its manufacturing may depend on faster digital adoption. The brief shows that the effects of new technologies differ across firms and industries, so digital industrial policy must weigh firm-level factors.","sources":["https://publication.aercafricalibrary.org/handle/123456789/3404"]}$rita$::jsonb, 'published'),
('opeds', 'financing-digital-industrialisation-in-south-africa-emerging-issues', $rita${"title":"Financing digital industrialisation in South Africa: emerging issues","outlet":"CCRED-IDTT Policy Brief 2023/5","date":"2023-03","authors":["Nyamwena","Avenyo"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT-2022-2023-PB5_Finance-and-digitalisation.pdf","summary":"Survey evidence from South African manufacturers shows that finance matters for the adoption of digital technologies. The brief sets out the emerging issues in financing digital industrialisation.","sources":["https://www.competition.org.za/s/IDTT-2022-2023-PB5_Finance-and-digitalisation.pdf","https://www.competition.org.za/idtt-year-6"]}$rita$::jsonb, 'published'),
('opeds', 'global-value-chains-job-creation-and-job-destruction-among-firms-in', $rita${"title":"Global value chains, job creation and job destruction among firms in South Africa","outlet":"STEG Policy Brief, Growth Research Platform (CEPR)","date":"2026-03","authors":["Ndubuisi","Owusu"],"kind":"policy-brief","programme":"INN","outletUrl":"https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","summary":"Using data on the universe of formal manufacturing firms in South Africa, the brief finds that joining global value chains brings a net job gain. The gain is driven by firms entering GVCs, largely younger and smaller ones; firms that stay in GVCs shed jobs overall.","keyPoints":["GVC integration is linked to net job gains at the firm level.","Continuous GVC participants show an overall net job loss.","Gains are driven mainly by younger and smaller firms."],"sources":["https://grp.cepr.org/publications/steg-policy-brief/global-value-chains-job-creation-and-job-destruction-among-firms","https://steg.cepr.org/sites/default/files/2023-08/WP073%20NdubuisiOwusuGlobalValueChainsJobCreation.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'how-global-value-chains-are-reshaping-jobs-in-south-africa', $rita${"title":"How global value chains are reshaping jobs in South Africa","outlet":"LSE Business Review","date":"2026-09","authors":["Ndubuisi","Owusu"],"kind":"research-blog","programme":"INN","outletUrl":"https://blogs.lse.ac.uk/businessreview/2026/09/30/how-global-value-chains-are-reshaping-jobs-in-south-africa/","summary":"Global value chains both create and destroy jobs in South Africa. Net gains come from new, small and young firms entering GVCs, while long-standing participants shed jobs.","sources":["https://steg.cepr.org/projects/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa"]}$rita$::jsonb, 'published'),
('opeds', 'implications-of-covid-19-on-digital-transformation-in-south-africa', $rita${"title":"Implications of COVID-19 on digital transformation in South Africa","outlet":"CCRED-IDTT Policy Brief 2022/08","date":"2022-07","authors":["Avenyo","Bell","Nyamwena"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.competition.org.za/s/IDTT5-PB8-Implications-of-COVID-19-on-digital-transformation-in-South-Africa.pdf","summary":"Drawing on a survey of 516 South African manufacturing firms, the brief shows how COVID-19 interacted with the shift to digital technologies. Uneven digital uptake weakens the resilience of the firms and industries most exposed to shocks.","sources":["https://www.competition.org.za/s/IDTT5-PB8-Implications-of-COVID-19-on-digital-transformation-in-South-Africa.pdf","https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-04-avenyo-e-k--bell-j-f--nyamwena-j--march-2023.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'informal-workers-in-senegal-mali-and-burkina-faso-hit-harder-by-covid-19', $rita${"title":"Informal workers in Senegal, Mali and Burkina Faso have been hit harder by COVID-19","outlet":"The Conversation","date":"2021-09","authors":["Balde","Boly","Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://theconversation.com/informal-workers-in-senegal-mali-and-burkina-faso-have-been-hit-harder-by-covid-19-168122","summary":"A survey of 900 people in Senegal, Mali and Burkina Faso in spring 2020 found that informal workers were more likely to lose their jobs, see their earnings fall and struggle to meet basic needs. The authors set out what this means for social protection and support for small businesses.","keyPoints":["Informal workers were more likely to lose their jobs and earnings.","The pattern held in high-risk sectors too.","Informal workers were more likely to struggle to meet basic needs."],"sources":["https://theconversation.com/informal-workers-in-senegal-mali-and-burkina-faso-have-been-hit-harder-by-covid-19-168122","https://unu.edu/article/informal-workers-senegal-mali-and-burkina-faso-have-been-hit-harder-covid-19"]}$rita$::jsonb, 'published'),
('opeds', 'localisation-and-industrialisation-nexus-lessons-for-south-africa', $rita${"title":"Localisation and industrialisation nexus: lessons for South Africa","outlet":"CCRED-IDTT Policy Brief 2023/1","date":"2023-03","authors":["Nyamwena","Avenyo","Bosiu"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.competition.org.za/s/IDTT-2022-2023-PB1_Localisation-and-Industrialisation-Nexus.pdf","summary":"A policy brief on how localisation policy connects to industrialisation, and what South Africa can learn from it.","sources":["https://www.competition.org.za/s/IDTT-2022-2023-PB1_Localisation-and-Industrialisation-Nexus.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'more-about-the-melody-less-about-the-volume-financing-industrial', $rita${"title":"More melody, less volume: financing industrial transformation across Africa","outlet":"OPEC Fund Quarterly, 2026 Q2","date":"2026-05","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"IND","outletUrl":"https://publications.opecfund.org/OFQ-2026-2/8/","summary":"The debate on financing Africa’s green industrial shift focuses too much on the size of the funding gap. The authors argue the deeper constraint is the structure, quality and purpose of finance, and how well it is aligned with industrial development.","sources":["https://publications.opecfund.org/OFQ-2026-2"]}$rita$::jsonb, 'published'),
('opeds', 'no-chips-no-power-why-africa-must-enter-the-global-semiconductor-value', $rita${"title":"No chips, no power: why Africa must enter the global semiconductor value chain","outlet":"Governance & Development Advisory","date":"2026-02","authors":["Ndubuisi"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.gdadvisory.org/_files/ugd/aeda26_794d17f3e3c44834ae6d49940b25e8c4.pdf","summary":"Africa cannot power its green and digital future without a place in the semiconductor value chain. The brief argues for entering feasible segments, such as chip design, assembly, testing and packaging, and power electronics, collectively through the AfCFTA.","sources":["https://www.gdadvisory.org/blog"]}$rita$::jsonb, 'published'),
('opeds', 'south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it', $rita${"title":"South Africa is failing to ride the digital revolution wave. What it needs to do","outlet":"The Conversation","date":"2021-12","authors":["Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://theconversation.com/south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it-needs-to-do-171515","summary":"A survey of 516 South African firms shows the uptake of digital technologies has been slow and uneven. Premature deindustrialisation has left a small, undiversified production base, which makes it harder to meet the basics: connectivity, energy and digital skills.","sources":["https://newsletter.po.creamermedia.com/article/south-africa-is-failing-to-ride-the-digital-revolution-wave-what-it-needs-to-do-2021-12-03","https://pure.uj.ac.za/en/clippings/why-south-africa-is-failing-to-ride-the-digital-revolution-wave-a/"]}$rita$::jsonb, 'published'),
('opeds', 'south-africas-electricity-crises-have-left-productive-scars-its-green', $rita${"title":"South Africa’s electricity crises have left productive scars. Its green transition must confront them","outlet":"Pan African Visions","date":"2026-07","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"EN","outletUrl":"https://panafricanvisions.com/2026/07/south-africas-electricity-crises-have-left-productive-scars-its-green-transition-must-confront-them/","summary":"Years of power cuts left productive scars: lost manufacturing capacity, investment, export capability and learning that persist after supply improves. A green transition that ignores them may deliver cleaner electricity while reproducing industrial weakness.","keyPoints":["Outages reduced investment, employment and exports, mainly among electricity-intensive manufacturers.","Reliable power alone will not bring investment back.","Energy reform must become productive reconstruction."],"sources":["https://panafricanvisions.com/2026/07/south-africas-electricity-crises-have-left-productive-scars-its-green-transition-must-confront-them/"]}$rita$::jsonb, 'published'),
('opeds', 'south-africas-path-to-the-4ir-the-role-of-digital-skills', $rita${"title":"South Africa’s path to the 4IR: the role of digital skills","outlet":"Engineering News","date":"2021-03","authors":["Avenyo"],"kind":"op-ed","programme":"INN","outletUrl":"https://www.engineeringnews.co.za/article/opinion-south-africas-path-to-the-4ir-the-role-of-digital-skills-2021-03-04","summary":"For a middle-income technological follower like South Africa, the challenge is to modernise existing capabilities and infrastructure. The Industrial Development Think Tank argues that building digital skills in manufacturing is central to that.","sources":["https://www.engineeringnews.co.za/article/opinion-south-africas-path-to-the-4ir-the-role-of-digital-skills-2021-03-04/searchString:Bell"]}$rita$::jsonb, 'published'),
('opeds', 'technological-capability-and-industrialisation-in-africa', $rita${"title":"Technological capability and industrialisation in Africa","outlet":"SARChI Industrial Development Policy Brief 2024-03","date":"2024-03","authors":["Mensah","Ndubuisi"],"kind":"policy-brief","programme":"INN","outletUrl":"https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-pb2024-03-mensah-ndubuisi-technological-capability.pdf","summary":"Little is known about how technological capability shapes industrialisation in Africa. The brief measures capability along four dimensions (preconditions, infrastructure, technology imports and technological effort) and shows that capabilities spill over borders through intra-African trade.","sources":["https://uj.ac.za/wp-content/uploads/2021/10/sarchi-pb2024-03-mensah-ndubuisi-technological-capability.pdf"]}$rita$::jsonb, 'published'),
('opeds', 'the-new-era-of-industrial-policy-in-africa-from-sdg-assessment-to', $rita${"title":"The new era of industrial policy in Africa: from SDG assessment to policy solutions","outlet":"UNIDO IID Policy Brief 20","date":"2025-03","authors":["Asiama","Avenyo","Habiyaremye","Ncube","Tregenna","Donnelly","Lavopa"],"kind":"policy-brief","programme":"IND","outletUrl":"https://www.unido.org/publications/policy-briefs","summary":"Linked to the Africa launch of UNIDO’s Industrial Development Report 2024, the brief assesses Africa’s progress on the industry-related SDGs and argues that industrial policy aligned with the SDGs can drive innovation, decent jobs and climate mitigation.","sources":["https://www.unido.org/publications/policy-briefs","https://www.unido.org/news/unido-launches-industrial-development-report-2024-africa"]}$rita$::jsonb, 'published'),
('opeds', 'the-policy-coherence-trap-south-africas-next-industrial-policy-challenge', $rita${"title":"The policy coherence trap: South Africa’s next industrial policy challenge","outlet":"Governance & Development Advisory","date":"2026-09","authors":["Ndubuisi","Avenyo"],"kind":"op-ed","programme":"IND","outletUrl":"https://www.gdadvisory.org/post/the-policy-coherence-trap-south-africa-s-next-industrial-policy-challenge","summary":"South Africa has one of Africa’s most sophisticated industrial policy architectures, yet transformation remains elusive. Aligned strategies and institutions are not enough: coherence must be built around the productive bottlenecks that hold firms back.","sources":["https://www.gdadvisory.org/blog"]}$rita$::jsonb, 'published'),
('opeds', 'trading-for-africas-structural-transformation-why-fit-matters-more', $rita${"title":"Trading for Africa’s structural transformation: why fit matters more","outlet":"Development Front","date":"2026-09","authors":["Ndubuisi","Owusu","Kassa"],"kind":"research-blog","programme":"IND","outletUrl":"https://dev-front.org/trading-for-africas-structural-transformation-why-fit-matters-more/","summary":"Drawing on their study of 52 African countries (2000–2022), the authors argue that what drives structural change is not whether imported inputs come from the North or the South, but how well they fit local capabilities.","sources":["https://onlinelibrary.wiley.com/doi/10.1111/twec.70049"]}$rita$::jsonb, 'published'),
