('people', 'elvis-korku-avenyo', $rita${"title":"Elvis Korku Avenyo","name":"Elvis Korku Avenyo","group":"lead","role":"Programme lead","base":"Johannesburg","authorKey":"Avenyo","focus":"Innovation, industrial development, firms and labour markets","bio":"Associate Professor of Development Economics at the SARChI Chair in Industrial Development, University of Johannesburg. His work spans innovation, technology adoption, industrial development, labour markets and firm behaviour, including the informal economy. He was previously a Senior Researcher at CCRED and a Research Officer at Oxford’s Technology and Management Centre for Development (TMCD). PhD, UNU-MERIT / Maastricht University.","programmes":["EN","INN"],"focusTags":["Innovation","Industrial development","Digital technologies","Labour markets","Informality"],"links":{"site":"https://sites.google.com/view/elvis-korku-avenyo"},"awards":["2025 Middleton Award (South African Journal of Economics)","Overall Best Conference Paper, African Economic Conference 2022 (Mauritius)","Africa Oxford Initiative travel grant (CSAE 2019)","OpenAIR Queen Elizabeth Scholar","UJ Global Excellence and Stature award"],"expertise":["Electricity crises","Manufacturing","Digital technologies","Informal economy"],"consentToList":true}$rita$::jsonb, 'published'),
('people', 'gideon-ndubuisi', $rita${"title":"Gideon Ndubuisi","name":"Gideon Ndubuisi","group":"lead","role":"Programme lead","base":"Delft","authorKey":"Ndubuisi","focus":"Green industrialisation, transition minerals, industrial policy","bio":"Assistant Professor of Economics at Delft University of Technology (TU Delft). His research covers the political economy of Africa’s green structural transformation, with a focus on green industrialisation, transition minerals and industrial policy, alongside trade, global value chains and productivity. He writes RITA’s weekly Policy Insights. He has worked with UNIDO, the World Bank, the African Development Bank, the European Commission, ACET, UNU-WIDER, APRI and the IFC, and was previously at the German Development Institute (IDOS), where he helped set up the Research Network Sustainable Supply Chains. PhD, UNU-MERIT / Maastricht University.","bioTbc":false,"programmes":["IND","MIN"],"focusTags":["Green industrialisation","Transition minerals","Industrial policy","Global value chains","Productivity"],"links":{"site":"https://sites.google.com/view/gideonndubuisi"},"expertise":["Transition minerals","Industrial policy","Green hydrogen","AfCFTA"],"consentToList":true}$rita$::jsonb, 'published'),
('people', 'marcel-kempers', $rita${"title":"Marcel Kempers","name":"Marcel Kempers","group":"staff","role":"Curator & website lead","base":"","authorKey":"Kempers","focus":"E-mobility, transport and work in African cities","bio":"Marcel Kempers curates and runs the RITA website. His research looks at e-mobility and informal transport work in African cities, including electric motorcycle taxis (boda bodas) in Nairobi. MSc, Delft University of Technology.","bioTbc":false,"programmes":["INN"],"focusTags":["E-mobility","Boda bodas","Nairobi","Informal work","Transport"],"links":{},"awards":[],"expertise":[],"consentToList":true}$rita$::jsonb, 'published'),
('programmes', 'energy-and-industry', $rita${"code":"EN","number":"03","colour":"sun","title":"Energy & industry","short":"Electricity and firms, solar PV, EVs, hydrogen.","intro":"How electricity reliability, renewable energy and new energy technologies shape what African firms can make, and where green industries can take root.","keyQuestions":["What do electricity crises cost firms in jobs, investment and exports?","Can Africa manufacture solar PV, batteries and EVs competitively?","Is green hydrogen a strategy or a distraction?"],"featured":["jobs-investments-and-exporting-the-real-effects-of-electricity-crises","dancing-on-the-grid-electricity-crises-manufacturing-energy","solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage"],"lead":"elvis-korku-avenyo","photo":"Power station, grid or solar farm"}$rita$::jsonb, 'published'),
('programmes', 'green-industrialisation', $rita${"code":"IND","number":"01","colour":"malachite","title":"Green industrialisation & policy","short":"Political economy, learning states, private sector.","intro":"How African states can build the institutions, coalitions and finance to turn the green transition into manufacturing, jobs and structural change.","keyQuestions":["What kind of state does green industrial policy need?","How should finance be structured, not just scaled?","How do regional markets (AfCFTA) create demand for African production?"],"featured":["gendering-structural-change-and-green-transition-in-africa-implications","chinese-economic-ties-and-low-carbon-industrialization-in-africa","greening-manufacturing-technology-intensity-and-co2-emissions-in"],"lead":"gideon-ndubuisi","photo":"Industrial park"}$rita$::jsonb, 'published'),
('programmes', 'innovation-firms-work', $rita${"code":"INN","number":"04","colour":"ink","title":"Innovation, firms & work","short":"Capabilities, digital tech, informality, jobs.","intro":"How African firms, formal and informal, learn, innovate, adopt digital technology and create good jobs.","keyQuestions":["How do firms build technological capabilities?","When do value chains and digital technologies create jobs rather than destroy them?","What role does the informal economy play in industrial learning?"],"featured":["global-value-chains-and-the-innovativeness-of-firms-in-africa","determinants-of-digital-technologies-adoption-in-south-african","the-employment-impact-of-product-innovations-in-sub-saharan-africa"],"lead":"elvis-korku-avenyo","photo":"Workshop, maker space or informal enterprise"}$rita$::jsonb, 'published'),
('programmes', 'transition-minerals', $rita${"code":"MIN","number":"02","colour":"laterite","title":"Transition minerals & value chains","short":"Processing, regional value chains, royalties.","intro":"How African countries can move from extracting transition minerals to processing, manufacturing and regional value chains.","keyQuestions":["What does it take to regionalise mineral value chains?","When does local processing pay off?","How should royalty and fiscal regimes adapt to volatility?"],"featured":["regionalizing-green-transition-minerals-for-structural-transformation","critical-minerals-and-routes-to-diversification-in-africa-linkages","adaptive-royalty-formulations-for-critical-minerals-amid-fiscal"],"lead":"gideon-ndubuisi","photo":"Copper / cobalt / lithium processing"}$rita$::jsonb, 'published'),
('projects', 'african-business-and-society', $rita${"title":"African Business and Society (ABS)","projectStatus":"ongoing","startYear":2026,"endYear":2030,"period":"2026–2030","funder":"DANIDA","partners":["Copenhagen Business School","University of Johannesburg","University of Ghana","University of Nairobi"],"team":["elvis-korku-avenyo"],"programme":"INN","preRita":false,"summary":"A five-year research collaboration on the role of business in African societies.","budget":"USD 5.2m","photo":"Business & society","description":"A five-year research collaboration on the role of business in African societies, funded by DANIDA. Copenhagen Business School works with the universities of Johannesburg, Ghana and Nairobi.","sources":["https://sites.google.com/view/elvis-korku-avenyo/awardsprojects"]}$rita$::jsonb, 'published'),
('projects', 'covid-19-health-expenditure-shocks-ghana', $rita${"title":"COVID-19 health expenditure shocks and welfare in Ghana","projectStatus":"ongoing","funder":"AERC","team":["elvis-korku-avenyo"],"summary":"Health expenditure shocks, poverty and welfare in Ghana.","preRita":true,"description":"An AERC collaborative project on health financing gaps and vulnerabilities in Africa due to COVID-19 (grant RC 22519). With Martin Ayanore and Davina Osei, it studies catastrophic health expenditure shocks, poverty and welfare loss in Ghana, and which financing mechanisms mattered.","partners":["African Economic Research Consortium (AERC)"],"sources":["https://publication.aercafricalibrary.org/handle/123456789/3696","https://sites.google.com/view/elvis-korku-avenyo/awardsprojects","https://sites.google.com/view/elvis-korku-avenyo/research"]}$rita$::jsonb, 'published'),
('projects', 'critical-minerals-and-structural-transformation', $rita${"title":"Critical minerals and structural transformation in Africa","projectStatus":"ongoing","funder":"SCIS, Wits School of Geosciences, Wits Mining Institute, SARChI Industrial Development","partners":["Southern Centre for Inequality Studies (SCIS), Wits","Wits School of Geosciences","Wits Mining Institute","SARChI Industrial Development, University of Johannesburg"],"team":["elvis-korku-avenyo"],"programme":"MIN","preRita":false,"summary":"Research on how Africa’s critical minerals can drive structural transformation.","photo":"Mine site","sources":["docs/brief/CONTENT-SOURCES.md §9"]}$rita$::jsonb, 'published'),
('projects', 'digital-technologies-and-manufacturing-performance', $rita${"title":"Digital technologies and manufacturing performance in South Africa","projectStatus":"completed","funder":"AERC","team":["elvis-korku-avenyo"],"externalTeam":["Bell"],"programme":"INN","summary":"How digital technology adoption affects South African manufacturers.","preRita":true,"description":"An AERC-funded study of how disruptive digital technologies affect the performance of South African manufacturing firms, using firm-level survey data.","endYear":2022,"period":"2022","partners":["African Economic Research Consortium (AERC)"],"sources":["http://publication.aercafricalibrary.org/handle/123456789/3444","https://ideas.repec.org/e/pav90.html"]}$rita$::jsonb, 'published'),
('projects', 'electricity-crises-in-south-africa', $rita${"title":"Electricity crises in South Africa: jobs, investment, exporting and manufacturing vulnerability","projectStatus":"completed","funder":"UNU-WIDER (SA-TIED phase II)","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Asiama"],"programme":"EN","summary":"Firm-level evidence on what South Africa’s electricity crises cost manufacturers.","preRita":true,"description":"Research within UNU-WIDER's Southern Africa—Towards Inclusive Economic Development (SA-TIED) programme on what South Africa's electricity crises cost manufacturing. It builds an index of sub-sector energy vulnerability from input–output tables and uses firm-level tax data to trace effects on jobs, capital investment and exports.","endYear":2024,"period":"2024","partners":["UNU-WIDER","SA-TIED"],"sources":["https://sa-tied.wider.unu.edu/article/jobs-investments-and-exporting-the-real-effects-of-electricity-crises-in-south-africa","https://ideas.repec.org/p/unu/wpaper/wp-2024-41.html","https://wider.unu.edu/opportunity/south-africas-electricity-crisis-macroeconomic-macro-sectoral-and-fiscal-consequences"]}$rita$::jsonb, 'published'),
('projects', 'exporters-and-gvc-participation-in-south-africa', $rita${"title":"Exporters and GVC participation in South Africa","projectStatus":"completed","funder":"UNU-WIDER SA-TIED (with National Treasury, SARS)","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Mazzi"],"programme":"INN","summary":"Firm-level evidence from South African tax data on exporters and value chains.","preRita":true,"description":"Research within UNU-WIDER's SA-TIED programme using firm-level tax data from the South African Revenue Service and National Treasury to study exporters and their participation in global value chains.","endYear":2020,"period":"2020","partners":["UNU-WIDER","SA-TIED","National Treasury","South African Revenue Service"],"sources":["docs/brief/CONTENT-SOURCES.md §7, §9 (WIDER WP 2020/145)"]}$rita$::jsonb, 'published'),
('projects', 'gvc-participation-and-innovation-in-africa', $rita${"title":"GVC participation and innovation in Africa","projectStatus":"completed","funder":"AERC","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Mensah","Sakyi"],"programme":"INN","summary":"Firm-level evidence on global value chains and innovation in African firms.","preRita":true,"description":"Part of AERC's collaborative project on value chain development, trade and economic transformation in Africa. Using World Bank Enterprise Survey data, it asks whether firms in global value chains innovate more, and how gains spread to other firms.","endYear":2022,"period":"2022","partners":["African Economic Research Consortium (AERC)"],"sources":["https://publication.aercafricalibrary.org/handle/123456789/3407","https://aercafrica.org/?p=18411","https://sites.google.com/view/elvis-korku-avenyo/awardsprojects"]}$rita$::jsonb, 'published'),
('projects', 'regionalizing-green-transition-minerals', $rita${"title":"Regionalizing green transition minerals","projectStatus":"completed","endYear":2025,"period":"2025","funder":"World Bank","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Owusu","Kassa"],"programme":"MIN","summary":"World Bank report on regional value chains for Africa’s transition minerals.","preRita":true,"description":"A World Bank–commissioned study of Africa's green transition minerals. It maps deposits, reserves and production of 41 minerals across 48 countries, reviews national and regional mineral and industrial policies, and asks how countries can coordinate to build regional value chains instead of exporting raw.","partners":["World Bank, Office of the Chief Economist for the Africa Region"],"sources":["https://documents.worldbank.org/en/publication/documents-reports/documentdetail/099620011192519026","https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","https://theconversation.com/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report-290306"]}$rita$::jsonb, 'published'),
('projects', 'research-network-sustainable-supply-chains', $rita${"title":"Research Network Sustainable Supply Chains (co-founding)","projectStatus":"completed","funder":"German Development Institute (IDOS)","team":["gideon-ndubuisi"],"programme":"IND","summary":"Co-founding the IDOS research network on sustainable global supply chains.","preRita":true,"description":"A research network on sustainable global supply chains, led by four German institutes with the network office at DIE (now IDOS) and funded by Germany's development ministry (BMZ). Gideon Ndubuisi helped set up the network and served in its secretariat. It was publicly launched in March 2021.","startYear":2020,"endYear":2025,"period":"2020–2025","partners":["German Development Institute (DIE/IDOS)","German Institute for International and Security Affairs (SWP)","GIGA","Kiel Institute for the World Economy (IfW)"],"sources":["https://www.idos-research.de/en/research/description/details/research-network-sustainable-global-supply-chains/","https://www.giga-hamburg.de/en/events/23883088-launch-event-research-network-sustainable-global-supply-chains","https://idw-online.de/de/news764056"]}$rita$::jsonb, 'published'),
('projects', 'routes-to-diversification-in-africa', $rita${"title":"Routes to diversification in Africa (EDAR 2023 background)","projectStatus":"completed","endYear":2023,"period":"2023","funder":"UNCTAD","team":["elvis-korku-avenyo"],"externalTeam":["Andreoni"],"programme":"MIN","summary":"Four background papers on critical minerals for UNCTAD’s Economic Development in Africa Report 2023.","preRita":true,"description":"Four background papers for UNCTAD's Economic Development in Africa Report 2023 on critical minerals and routes to diversification: linkages and medium-high-tech supply chains, and case studies of renewable energy technologies in Morocco, batteries and mining equipment in South Africa, and mobile phone technologies in the DRC.","partners":["UNCTAD"],"sources":["https://unctad.org/system/files/non-official-document/edar2023_BP1_en.pdf"]}$rita$::jsonb, 'published'),
('projects', 'services-sector-acceleration', $rita${"title":"Services sector acceleration / Economic Transformation Database","projectStatus":"completed","funder":"UNU-WIDER & GGDC Groningen","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Owusu","Asiamah"],"programme":"IND","summary":"What drives growth accelerations in the services sector of developing countries.","preRita":true,"description":"Research within the UNU-WIDER Economic Transformation Database (ETD) project. Using ETD data for 50 developing countries from 1990 to 2018, it asks what drives growth accelerations in market and non-market services, and how this differs across regions.","startYear":2023,"endYear":2023,"period":"2023","partners":["UNU-WIDER","Groningen Growth and Development Centre (GGDC)"],"sources":["https://wider.unu.edu/publication/drivers-services-sector-growth-acceleration-developing-countries","https://www.wider.unu.edu/sites/default/files/Publications/Working-paper/PDF/wp2023-87-drivers-services-sector-growth-acceleration-developing-countries.pdf","https://unu.edu/projects/economic-transformation-database-etd.html"]}$rita$::jsonb, 'published'),
('projects', 'solar-pv-value-chain-in-africa', $rita${"title":"Solar PV value chain in Africa","projectStatus":"completed","funder":"APRI (Africa's Development Agenda for its Critical Raw Materials)","team":["gideon-ndubuisi","elvis-korku-avenyo"],"programme":"EN","summary":"Whether Africa can manufacture solar photovoltaic components competitively.","preRita":true,"description":"Part of APRI's Green and Transition Minerals collection. The study analyses critical minerals, trade and investment flows to ask whether African countries can manufacture solar PV, and makes the case for a regionalised PV strategy.","endYear":2024,"period":"2024","partners":["Africa Policy Research Institute (APRI)"],"sources":["https://afripoli.org/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","https://www.pv-magazine.com/2024/10/10/africa-needs-regional-strategy-for-pv-manufacturing/"]}$rita$::jsonb, 'published'),
('projects', 'sti-and-socio-economic-development-south-africa', $rita${"title":"Science, technology and innovation and socio-economic development in South Africa","projectStatus":"completed","funder":"Department of Science and Innovation, South Africa","team":["elvis-korku-avenyo"],"externalTeam":["Tregenna (PI)"],"programme":"INN","summary":"Research grant on STI and socio-economic development (Elvis Korku Avenyo, Co-PI).","preRita":true,"partners":["Department of Science and Innovation, South Africa"],"sources":["docs/brief/CONTENT-SOURCES.md §9"]}$rita$::jsonb, 'published'),
('projects', 'structural-change-gender-equality-acet', $rita${"title":"Structural change, gender equality and gender-transformative policy","projectStatus":"completed","funder":"ACET","team":["gideon-ndubuisi","elvis-korku-avenyo"],"externalTeam":["Chisoro"],"programme":"IND","summary":"Gender papers for the African Transformation Report 4.","preRita":true,"description":"Background research for ACET's fourth African Transformation Report, on gender equality and economic transformation. The paper uses panel data for 48 African countries from 1992 to 2019, with case studies of Ghana and South Africa, to show how structural change and the green transition affect gender employment gaps.","endYear":2024,"period":"2024","partners":["African Center for Economic Transformation (ACET)"],"sources":["https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","https://acetforafrica.org/research-and-analysis/insights-ideas/articles/call-for-authors-african-transformation-report-on-gender-equality-and-economic-transformation/"]}$rita$::jsonb, 'published'),
('projects', 'unido-idr-2026-background', $rita${"title":"Industrial Development Report 2026: background report","projectStatus":"completed","endYear":2025,"period":"2025","funder":"UNIDO","team":["elvis-korku-avenyo"],"externalTeam":["Tregenna","Asiama","Ncube"],"programme":"IND","summary":"Background report for chapter 5 of UNIDO’s Industrial Development Report 2026.","preRita":true,"description":"A background report for chapter 5 of UNIDO's Industrial Development Report 2026, on the future of industrialisation in sub-Saharan Africa: its bottlenecks and sectoral opportunities.","partners":["UNIDO"],"sources":["https://www.unido.org/idr/idr2026","docs/brief/CONTENT-SOURCES.md §6"]}$rita$::jsonb, 'published'),
('publications', 'adaptive-royalty-formulations-for-critical-minerals-amid-fiscal', $rita${"title":"Adaptive royalty formulations for critical minerals amid fiscal volatility and geopolitical uncertainty","publisher":"Resources Policy 116, 105900","year":2026,"authors":["Nwaila","et al."],"type":"journal","programmes":["MIN"],"externalUrl":"https://doi.org/10.1016/j.resourpol.2026.105900","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.resourpol.2026.105900","pdf":"https://zenodo.org/records/18195775","summary":"The paper proposes an Adaptive Royalty Architecture for critical minerals: a statutory ad valorem floor, a margin- or price-linked escalator, a downside price-variance buffer and a rules-based community dividend. It stress-tests the design on lithium, nickel and rare earth cases.","keyFindings":["The adaptive design improves downside cushioning relative to simple ad valorem royalties under baseline settings.","The authors report royalty-revenue volatility below 30%, royalties capped at 35% of operating cash flow and 25–30% of royalties earmarked for host regions.","The design is a hybrid of existing instruments rather than a wholly new one."],"methods":"Monte Carlo stress tests of lithium, nickel and rare earth cases over a 15-year horizon, comparing royalty regimes (not forecasts of project outcomes).","sources":["https://www.sciencedirect.com/science/article/pii/S0301420726000723","https://zenodo.org/records/18195775"]}$rita$::jsonb, 'published'),
('publications', 'african-economic-outlook-2024-contribution', $rita${"title":"African Economic Outlook 2024: Driving Africa’s Transformation: The Reform of the Global Financial Architecture","publisher":"African Development Bank","year":2024,"authors":["Ndubuisi"],"type":"report","programmes":["IND"],"externalUrl":"https://www.afdb.org/en/documents/african-economic-outlook-2024","regions":["Africa-wide"],"pdf":"https://research.trademarkafrica.com/wp-content/uploads/2024/10/AfDB-African-Economic-Outlook-2024-compressed.pdf","summary":"The African Development Bank's 2024 flagship report calls for reform of the global financial architecture to drive Africa's structural transformation, including a greater voice for Africa in multilateral development banks and international financial institutions. Gideon Ndubuisi contributed to the report.","keyFindings":["The report estimates Africa's financing gap for structural transformation at US$402.2 billion a year to 2030.","It argues that domestic resources alone will not be enough to finance Africa's transformation agenda."],"sources":["https://research.trademarkafrica.com/wp-content/uploads/2024/10/AfDB-African-Economic-Outlook-2024-compressed.pdf","https://allafrica.com/stories/202405310085.html"]}$rita$::jsonb, 'published'),
('publications', 'african-transformation-report-2025-contribution', $rita${"title":"African Transformation Report 2025 (contribution)","publisher":"ACET","year":2025,"authors":["Ndubuisi"],"type":"report","programmes":["IND"],"externalUrl":"https://acetforafrica.org/atr2025/","regions":["Africa-wide"],"summary":"ACET's 2025 African Transformation Report explores how closing gender gaps fuels Africa's economic transformation, using the African Transformation Index and the Gender Inequality Index to highlight persistent barriers and the policies that work.","sources":["https://acetforafrica.org/atr","https://acetforafrica.org/our-work/african-transformation-report/"]}$rita$::jsonb, 'published'),
('publications', 'being-a-boda-isnt-easy', $rita${"title":"Being a boda isn’t easy","type":"thesis","programmes":["INN"],"authors":["Kempers"],"authorOrderConfirmed":true,"publisher":"Delft University of Technology, MSc thesis","year":null,"regions":["East Africa"]}$rita$::jsonb, 'published'),
('publications', 'chinese-development-finance-and-labour-productivity-growth-in', $rita${"title":"Chinese development finance and labor productivity growth in developing countries","publisher":"SSRN Working Paper 4989817","year":2024,"authors":["Konte","Ndubuisi"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://papers.ssrn.com/sol3/papers.cfm?abstract_id=4989817","regions":["Global"],"authorOrderConfirmed":true,"pdf":"https://papers.ssrn.com/sol3/papers.cfm?abstract_id=4989817","summary":"Does Chinese development finance raise labour productivity growth in developing countries, and through which channel? Using concessional and commercial Chinese project finance, the paper finds that productivity gains work mainly within sectors rather than through labour moving between sectors.","keyFindings":["The productivity growth effect of Chinese finance works mainly through the within-sector component, not structural change between sectors.","Gains from concessional finance are larger where governance is weaker.","Gains from commercial loans are larger where governance is stronger."],"methods":"Chinese concessional and commercial project data for 128 developing countries, 2000–2016, with labour productivity growth decomposed into within-sector and between-sector components.","sources":["https://papers.ssrn.com/sol3/papers.cfm?abstract_id=4989817","https://www.researchgate.net/publication/384991780_Chinese_Development_Finance_and_Labor_Productivity_Growth_in_Developing_Countries"]}$rita$::jsonb, 'published'),
('publications', 'chinese-economic-ties-and-low-carbon-industrialization-in-africa', $rita${"title":"Chinese ties and low-carbon industrialization in Africa","publisher":"Energy Economics 144, 108352","year":2025,"authors":["Owusu","Tang","Ndubuisi"],"type":"journal","programmes":["IND"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S0140988325001768","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://repository.tudelft.nl/file/File_b862d598-038c-4825-85e8-f0fe5409ed56","summary":"The paper examines how Chinese greenfield investment in African manufacturing affects industrial carbon emissions. It finds that Chinese FDI inflows increased industrial emissions, especially when they targeted labour- and resource-intensive sectors.","keyFindings":["Chinese FDI inflows increased industrial carbon emissions in Africa.","The effect is strongest when Chinese FDI targets labour- and resource-intensive manufacturing.","Host-country environmental regulation moderates the effect, but not significantly, pointing to weak enforcement."],"methods":"Panel of Chinese greenfield FDI into manufacturing in 34 African countries, 2003–2014, estimated with a Lewbel instrumental variable approach.","sources":["https://www.bu.edu/gdp/2024/07/28/chinese-economic-ties-and-low-carbon-industrialization-in-africa/","https://merit.url.edu/en/publications/chinese-ties-and-low-carbon-industrialization-in-africa/","https://repository.tudelft.nl/file/File_b862d598-038c-4825-85e8-f0fe5409ed56"]}$rita$::jsonb, 'published'),
('publications', 'chinese-manufacturing-import-penetration-and-firm-performance-belt-and', $rita${"title":"Chinese manufacturing import penetration and firm performance: evidence from Belt and Road Initiative countries","publisher":"SARChI Industrial Development Working Paper 2024-06","year":2024,"authors":["Avenyo","Spinola","Tregenna"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://ideas.repec.org/p/adz/wpaper/2024-06.html","regions":["Global"],"authorOrderConfirmed":true,"pdf":"https://www.uj.ac.za/wp-content/uploads/2021/10/wp2024-06-avenyo-spinola-tregenna-chinese-manufacturing-import-penetration.pdf","summary":"The paper examines how Chinese manufacturing import penetration affects the performance of manufacturing firms in Belt and Road Initiative countries. Chinese imports crowd out firms' productive capacity while acting as a catalyst for their internationalisation.","keyFindings":["Chinese imports reduce productivity growth and employment, while firms' export capabilities rise.","Innovation and foreign licensing significantly moderate the adverse effects.","The effects are significant in middle-income countries and among small and medium-sized enterprises."],"methods":"World Bank Enterprise Survey firm data combined with UN Comtrade industry data for 59 BRI countries, 2011–2020, using a multi-level modelling approach.","sources":["https://ideas.repec.org/p/adz/wpaper/2024-06.html","https://ysi.ineteconomics.org/event/chinese-manufacturing-import-penetration-and-firm-performance-evidence-from-belt-and-road-initiative-countries/"]}$rita$::jsonb, 'published'),
('publications', 'clean-cryptocurrencies-and-media-environmental-attention', $rita${"title":"Dependence and risk spillovers among clean cryptocurrencies prices and media environmental attention","publisher":"Research in International Business and Finance 65, 101953","year":2023,"authors":["Ndubuisi","Urom"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.ribaf.2023.101953","externalUrl":"https://doi.org/10.1016/j.ribaf.2023.101953","pdf":"https://repository.tudelft.nl/file/File_a640495c-c03c-4f51-88b7-273c9a260837","summary":"The study examines the link between media attention to cryptocurrencies' environmental impact and the prices of clean cryptocurrencies. It finds strong connectedness, implying that clean cryptocurrency prices are influenced by attention on cryptocurrency sustainability.","keyFindings":["Clean cryptocurrency prices and cryptocurrency environmental attention are strongly connected.","Clean cryptocurrency prices are influenced by attention on cryptocurrency sustainability."],"methods":"TVP-VAR connectedness and wavelet methods.","sources":["https://repository.tudelft.nl/file/File_a640495c-c03c-4f51-88b7-273c9a260837"]}$rita$::jsonb, 'published'),
('publications', 'clean-energy-sectors-and-oil-price-uncertainty', $rita${"title":"Directional predictability and time-frequency spillovers among clean energy sectors and oil price uncertainty","publisher":"Quarterly Review of Economics and Finance 85, 326–341","year":2022,"authors":["Urom","Mzoughi","Ndubuisi","Guesmi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://ideas.repec.org/a/eee/quaeco/v85y2022icp326-341.html","summary":"The paper analyses the dependence between clean energy sectors and oil price uncertainty. Sector responses differ in direction and size depending on the sector, market conditions and investment horizon.","keyFindings":["Dependence and predictability from oil market uncertainty to clean energy sectors vary across market conditions and horizons.","Shock spillovers are weak in the short term and grow over intermediate and long horizons."],"methods":"Wavelet, cross-quantilogram and TVP-VAR models with stochastic volatility on six NASDAQ OMX Green Economy sector indices.","sources":["https://www.idos-research.de/en/others-publications/article/directional-predictability-and-time-frequency-spillovers-among-clean-energy-sectors-and-oil-price-uncertainty/"]}$rita$::jsonb, 'published'),
('publications', 'clean-investments-and-economic-policy-uncertainty', $rita${"title":"Dynamic dependence between clean investments and economic policy uncertainty","publisher":"UNU-MERIT Working Paper 2022-027","year":2022,"authors":["Urom","Mzoughi","Ndubuisi","Guesmi"],"type":"working-paper","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://merit.unu.edu/publications/working-papers/abstract/?id=9378","pdf":"https://cris.maastrichtuniversity.nl/files/106567847/wp2022_027.pdf","summary":"The paper examines how clean investments across sectors respond to economic policy uncertainty, using the NASDAQ OMX Green Economy sectoral indexes. Dependence and predictability vary across market conditions and horizons, so the diversification benefits of clean energy stocks depend on sector, market conditions and horizon.","keyFindings":["Dependence and directional predictability of clean energy returns from policy uncertainty vary across market conditions and horizons.","Policy uncertainty and clean energy sectors are weakly connected in the short term and more strongly over medium and long horizons."],"methods":"NASDAQ OMX Green Economy sectoral indexes analysed with wavelet and cross-quantilogram methods and a time-varying parameter VAR with stochastic volatility.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=9378","https://ideas.repec.org/p/unm/unumer/2022027.html"]}$rita$::jsonb, 'published'),
('publications', 'coherency-and-predictability-between-stocks-of-ai-and-energy', $rita${"title":"Exploring the coherency and predictability between the stocks of artificial intelligence and energy corporations","publisher":"Financial Innovation 10(1), 128","year":2024,"authors":["Urom","Ndubuisi","Mzoughi","Guesmi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1186/s40854-024-00609-3","externalUrl":"https://doi.org/10.1186/s40854-024-00609-3","pdf":"https://repository.tudelft.nl/file/File_702c84e6-ec13-4ea4-abe5-c3e8f4be0cb9","summary":"The paper studies links between artificial intelligence investments and eight energy-focused sectors. It finds significant dependence and connectedness, especially over intermediate and long-term investment horizons, and a relationship that has grown stronger since the COVID-19 pandemic.","keyFindings":["AI and energy stocks show significant dependence and connectedness, especially over intermediate and long-term horizons.","The relationship has become stronger since the COVID-19 pandemic.","Directional predictability from AI to energy varies by sector, horizon and market conditions."],"methods":"Wavelet coherence, Cross-Quantilogram and time-varying parameter VAR (TVP-VAR) estimation.","sources":["https://ujcontent.uj.ac.za/esploro/outputs/journalArticle/Exploring-the-coherency-and-predictability-between/9946809907691","https://jfin-swufe.springeropen.com/articles/10.1186/s40854-024-00609-3"]}$rita$::jsonb, 'published'),
('publications', 'contractual-frictions-and-the-patterns-of-trade-the-role-of-generalized', $rita${"title":"Contractual frictions and the patterns of trade: the role of generalized trust","publisher":"Journal of International Trade & Economic Development 29(7), 775–796","year":2020,"authors":["Ndubuisi"],"type":"journal","programmes":["INN"],"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://ideas.repec.org/a/taf/jitecd/v29y2020i7p775-796.html","pdf":"https://mpra.ub.uni-muenchen.de/97055/1/MPRA_paper_97055.pdf","summary":"The paper looks at informal contracting institutions, measured by generalised trust, as a source of comparative advantage. Countries with higher trust export relatively more in industries prone to contractual frictions, which may explain why countries with weak formal institutions can still hold a cost advantage in contract-intensive industries.","keyFindings":["Higher-trust countries export relatively more in industries prone to contractual frictions.","Higher-trust countries enter more export markets and ship more products to each destination."],"sources":["https://ideas.repec.org/a/taf/jitecd/v29y2020i7p775-796.html","https://mpra.ub.uni-muenchen.de/97055/"]}$rita$::jsonb, 'published'),
('publications', 'contribution-jrc111430', $rita${"title":"Contribution (JRC111430)","publisher":"European Commission Joint Research Centre","year":null,"authors":["Ndubuisi"],"type":"report","programmes":["IND"],"externalUrl":"https://publications.jrc.ec.europa.eu/repository/handle/JRC111430"}$rita$::jsonb, 'published'),
('publications', 'coping-during-covid-19-family-businesses-and-social-assistance-in', $rita${"title":"Coping during COVID-19: family businesses and social assistance in Nigeria","publisher":"Covid Economics: Vetted and Real-Time Papers 51, 159–184 (CEPR)","year":2020,"authors":["Avenyo","Ndubuisi"],"type":"journal","programmes":["INN"],"externalUrl":"https://cepr.org/publications/covid-economics-issue-51","regions":["West Africa"],"authorOrderConfirmed":true,"summary":"The paper examines how changes in income and social assistance during the COVID-19 pandemic relate to the coping strategies of family business owners in Nigeria.","keyFindings":["Family business owners who lost income were more likely to show a higher coping level.","Owners who received social assistance were also more likely to show a higher coping level."],"methods":"Nigeria Baseline COVID-19 National Longitudinal Phone Survey 2020 (World Bank high-frequency phone survey).","sources":["https://www.idos-research.de/en/others-publications/article/coping-during-covid-19-family-businesses-and-social-assistance-in-nigeria/"]}$rita$::jsonb, 'published'),
('publications', 'covid-19-lockdowns-and-africas-informal-sector-lessons-from-ghana', $rita${"title":"COVID-19, lockdowns and Africa’s informal sector: lessons from Ghana","publisher":"UNU-MERIT Working Paper 2020-028","year":2020,"authors":["Avenyo","Francois","Zinyemba"],"type":"working-paper","programmes":["INN"],"regions":["West Africa"],"authorOrderConfirmed":true,"externalUrl":"https://www.merit.unu.edu/publications/working-papers/abstract/?id=8534","pdf":"https://www.merit.unu.edu/publications/working-papers/abstract/?id=8534","summary":"Using survey data on informal enterprises in Accra and Tema, the paper estimates the likely effects of COVID-19 lockdowns on Ghana's informal sector. Because the lockdown affects business performance, COVID-19 may widen or create gender and spatial gaps in informal enterprise performance.","keyFindings":["There is an unexplained spatial gap in sales between informal owners in Accra and Tema.","There is no gender gap in sales or innovation, but there are gender gaps in how firm size affects current sales.","COVID-19 may widen or create gender and spatial gaps in informal enterprise performance."],"methods":"Survey data on informal enterprises in Accra and Tema, Ghana, with regression analysis.","sources":["https://www.merit.unu.edu/publications/working-papers/abstract/?id=8534","https://cris.maastrichtuniversity.nl/en/publications/covid-19-lockdowns-and-africas-informal-sector-lessons-from-ghana/"]}$rita$::jsonb, 'published'),
('publications', 'critical-minerals-and-routes-to-diversification-in-africa-batteries', $rita${"title":"Critical minerals and routes to diversification in Africa: opportunities for diversification into batteries and fuel cells and mining equipment technologies. The case of South Africa","publisher":"UNCTAD, Economic Development in Africa Report 2023, background paper","year":2023,"authors":["Andreoni","Avenyo"],"type":"background-paper","programmes":["MIN"],"externalUrl":"https://unctad.org/node/42295","regions":["Southern Africa"],"project":"routes-to-diversification-in-africa","authorOrderConfirmed":true,"pdf":"https://unctad.org/system/files/non-official-document/edar2023_BP3_en.pdf","summary":"The paper maps the global battery and fuel cells value chain and analyses how South Africa can leverage its mineral resources to localise and capture value in mining equipment technologies. It draws industrial policy lessons for productive transformation across Africa.","methods":"Value chain mapping and an in-depth country case study of South Africa.","sources":["https://unctad.org/node/42295"]}$rita$::jsonb, 'published'),
('publications', 'critical-minerals-and-routes-to-diversification-in-africa-linkages', $rita${"title":"Critical minerals and routes to diversification in Africa: Linkages, pulling dynamics and medium-high-tech supply chains","publisher":"Background paper commissioned by the UNCTAD secretariat for the Economic Development in Africa Report 2023","year":2023,"authors":["Andreoni","Avenyo"],"type":"background-paper","programmes":["MIN"],"externalUrl":"https://unctad.org/system/files/non-official-document/edar2023_BP1_en.pdf","regions":["Africa-wide"],"project":"routes-to-diversification-in-africa","authorOrderConfirmed":true,"pdf":"https://unctad.org/system/files/non-official-document/edar2023_BP1_en.pdf","sources":["https://thecommonwealth-ilibrary.org/index.php/comsec/catalog/download/1134/1231/9824?inline=1"]}$rita$::jsonb, 'published'),
('publications', 'critical-minerals-and-routes-to-diversification-in-africa-mobile-phone', $rita${"title":"Critical minerals and routes to diversification in Africa: Opportunities for diversification into mobile phone technologies – the case of Democratic Republic of Congo","publisher":"UNCTAD, Economic Development in Africa Report 2023, background paper 4","year":2023,"authors":["Andreoni","Avenyo"],"type":"background-paper","programmes":["MIN"],"externalUrl":"https://unctad.org/node/42296","regions":["Africa-wide"],"project":"routes-to-diversification-in-africa","authorOrderConfirmed":true,"pdf":"https://unctad.org/system/files/non-official-document/edar2023_BP4_en.pdf","summary":"This background paper maps the global value chain for mobile phone technologies and examines how the Democratic Republic of Congo could use its mineral resources to localise and capture value in that chain. It also sets out the country's routes to diversification and technological deepening, including opportunities for regional coordination and industrial development.","sources":["https://unctad.org/node/42296"]}$rita$::jsonb, 'published'),
('publications', 'critical-minerals-and-routes-to-diversification-in-africa-renewable', $rita${"title":"Critical minerals and routes to diversification in Africa: opportunities for diversification into renewable energy technologies – the case of Morocco","publisher":"UNCTAD, background paper for the Economic Development in Africa Report 2023","year":2023,"authors":["Andreoni","Avenyo"],"type":"background-paper","programmes":["MIN"],"externalUrl":"https://unctad.org/system/files/non-official-document/edar2023_BP2_en.pdf","regions":["North Africa"],"project":"routes-to-diversification-in-africa","authorOrderConfirmed":true,"pdf":"https://unctad.org/system/files/non-official-document/edar2023_BP2_en.pdf","summary":"The paper maps the opportunities and challenges for Morocco to diversify into renewable energy technology value chains, and sets out a framework for how the country could localise and capture value in those supply networks.","keyFindings":["It identifies two routes to diversification: moving from adopter to producer of solar and solar battery technologies, and electric vehicle batteries and the circular economy.","Regional coordination and industrial development are treated as part of the routes to diversification."],"methods":"In-depth country case study of Morocco.","sources":["https://unctad.org/node/42294"]}$rita$::jsonb, 'published'),
('publications', 'dancing-on-the-grid-electricity-crises-manufacturing-energy', $rita${"title":"Dancing on the grid: Electricity crises, energy vulnerability, and manufacturing jobs in South Africa","publisher":"Energy Policy 202, 114534","year":2025,"authors":["Ndubuisi","Avenyo","Asiama"],"type":"journal","programmes":["EN"],"externalUrl":"https://doi.org/10.1016/j.enpol.2025.114534","doi":"10.1016/j.enpol.2025.114534","regions":["Southern Africa"],"project":"electricity-crises-in-south-africa","authorOrderConfirmed":true,"pdf":"https://wider.unu.edu/publication/dancing-grid-electricity-crises-manufacturing-energy-vulnerability-and-jobs-south","summary":"The paper builds an index of manufacturing sub-sector energy vulnerability from South Africa's input–output matrices and uses it to estimate how electricity crises affect manufacturing jobs. Electricity crises are linked to significant job losses, and the damage is greater in more energy-vulnerable sectors.","keyFindings":["Energy vulnerability varies significantly across manufacturing sub-sectors.","Electricity crises are associated with significant manufacturing job losses.","Job losses are larger in more energy-vulnerable sectors and affect both formal and informal jobs."],"methods":"Sub-sector energy vulnerability index built from South Africa's input–output matrices (1993–2021), used in an empirical model of manufacturing employment.","sources":["https://pure.uj.ac.za/en/publications/dancing-on-the-grid-electricity-crises-energy-vulnerability-and-m/","https://ideas.repec.org/a/eee/enepol/v202y2025ics0301421525000412.html","https://ideas.repec.org/p/unu/wpaper/wp-2024-41.html","https://wider.unu.edu/publication/dancing-grid-electricity-crises-manufacturing-energy-vulnerability-and-jobs-south"]}$rita$::jsonb, 'published'),
('publications', 'dependence-of-green-energy-markets-on-big-data-and-other-4ir', $rita${"title":"Dependence of green energy markets on big data and other fourth industrial revolution technologies","publisher":"Journal of International Financial Markets, Institutions & Money 96, 102061","year":2024,"authors":["Benkraiem","Guesmi","Ndubuisi","Urom","Vigne"],"type":"journal","programmes":["IND"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S1042443124001276","archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.intfin.2024.102061","summary":"The paper analyses dependence and connectedness between fourth industrial revolution technology markets (big data and artificial intelligence, blockchain, financial technology) and global and regional green energy markets, and the roles of market and macroeconomic factors in shock propagation.","methods":"Cross-spectral coherence and quantile-VAR connectedness on returns and volatility, across market conditions and investment horizons; US, Europe and Asia.","sources":["https://ideas.repec.org/a/eee/intfin/v96y2024ics1042443124001276.html"]}$rita$::jsonb, 'published'),
('publications', 'dependence-of-transition-minerals-on-global-clean-energy-and-technology', $rita${"title":"Dependence of transition minerals on global clean energy and technology stocks","publisher":"Finance Research Letters 85(A), 107809","year":2025,"authors":["Ndubuisi","Urom"],"type":"journal","programmes":["MIN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S1544612325010670","regions":["Global"],"authorOrderConfirmed":true,"pdf":"https://repository.tudelft.nl/file/File_e52f5dd6-49da-4f65-8f16-c36b354c30dd","summary":"The paper investigates the dynamic dependence of transition minerals on global clean energy and technology markets. Minerals respond asymmetrically, and their link to the technology market is stronger and more consistent.","keyFindings":["Aluminium, cobalt, copper and zinc tend to track technology market returns.","Granger causality runs more strongly from the clean energy market to transition minerals than from the technology market.","Clean energy market signals can serve as an early warning for policymakers in mineral-rich economies."],"methods":"Cross-quantilograms and Granger-causality in-mean and in-quantiles tests on market data from December 2018 to October 2024.","sources":["https://research.tudelft.nl/en/publications/dependence-of-transition-minerals-on-global-clean-energy-and-tech/"]}$rita$::jsonb, 'published'),
('publications', 'determinants-of-digital-technologies-adoption-in-south-african', $rita${"title":"Determinants of digital technologies’ adoption in South African manufacturing","publisher":"South African Journal of Economics 92(2), 235–259","year":2024,"authors":["Avenyo","Bell","Nyamwena"],"type":"journal","programmes":["INN"],"externalUrl":"https://onlinelibrary.wiley.com/doi/10.1111/saje.12378","doi":"10.1111/saje.12378","award":"2025 Middleton Award","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-wp-2022-13-avenyo-e-k--bell-j-f--nyamwena-j-october-2022.pdf","summary":"Adopting advanced digital technologies can raise firm productivity and competitiveness, but what drives adoption in developing-country manufacturing remains largely anecdotal. Using unique survey data on 516 South African manufacturing firms, the paper finds that innovation, foreign ownership, export exposure and skilled human capital propel adoption, while a lack of capital holds it back.","keyFindings":["Innovation, foreign ownership, exposure to export markets and higher-skilled human capital propel the adoption of digital technologies.","Lack of capital inhibits adoption.","The factors explaining adoption differ across business functions."],"methods":"Unique survey data on 516 South African manufacturing firms, analysed with a multivariate probit model.","sources":["https://ideas.repec.org/a/bla/sajeco/v92y2024i2p235-259.html","https://pure.uj.ac.za/en/publications/determinants-of-digital-technologies-adoption-in-south-african-ma/"]}$rita$::jsonb, 'published'),
('publications', 'digital-capabilities-in-south-african-manufacturing-firms-what-matters', $rita${"title":"Digital capabilities in South African manufacturing firms: what matters?","publisher":"CCRED-IDTT Working Paper 2023/06","year":2023,"authors":["Avenyo","Nyamwena"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://www.competition.org.za/s/IDTT-2022-2023-WP6_Digital-Capabilities-in-SA.pdf","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://www.competition.org.za/s/IDTT-2022-2023-WP6_Digital-Capabilities-in-SA.pdf"}$rita$::jsonb, 'published'),
('publications', 'digital-infrastructure-and-employment-in-services-evidence-from-sub', $rita${"title":"Digital infrastructure and employment in services: evidence from sub-Saharan African countries","publisher":"Telecommunications Policy 45(8), 102153","year":2021,"authors":["Ndubuisi","Otioma","Tetteh"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S0308596121000574","regions":["Africa-wide"],"authorOrderConfirmed":true,"summary":"The paper examines the link between digital infrastructure and employment in the services sector in sub-Saharan Africa, and the conditions under which the link is stronger or weaker.","keyFindings":["Digital infrastructure is positively associated with services-sector employment.","The positive effect grows as institutional quality improves.","Poor macroeconomic conditions weaken the effect, and the effect depends on education levels."],"methods":"Panel data for 45 sub-Saharan African countries, 1996–2017.","sources":["https://idos-research.de/en/others-publications/article/digital-infrastructure-and-employment-in-services-evidence-from-sub-saharan-african-countries","https://cris.maastrichtuniversity.nl/en/publications/digital-infrastructure-and-employment-in-services-evidence-from-s"]}$rita$::jsonb, 'published'),
('publications', 'digital-platforms-and-development-a-survey-of-the-literature', $rita${"title":"Digital platforms and development: a survey of the literature","publisher":"Innovation and Development 11(2-3), 303–321","year":2021,"authors":["Fu","Avenyo","Ghauri"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1080/2157930X.2021.1975361","doi":"10.1080/2157930X.2021.1975361","regions":["Global"],"authorOrderConfirmed":true,"pdf":"https://research.birmingham.ac.uk/files/177587903/Digital_platforms_and_development_a_survey_of_the_literature.pdf","summary":"A systematic literature review of how digital technology and platforms affect development in the modern economy. The authors group the literature into three main themes and point to directions for future research.","keyFindings":["Research on platforms and development has not been brought together from a development standpoint.","The literature falls into three main themes.","The review identifies directions for future research."],"methods":"Systematic literature review including quantitative, qualitative and mixed-methods studies worldwide.","sources":["https://ideas.repec.org/a/taf/riadxx/v11y2021i2-3p303-321.html","https://pure.uj.ac.za/en/publications/digital-platforms-and-development-a-survey-of-the-literature/","https://research.birmingham.ac.uk/files/177587903/Digital_platforms_and_development_a_survey_of_the_literature.pdf"]}$rita$::jsonb, 'published'),
('publications', 'disruptive-technologies-and-manufacturing-performance-in-south-africa', $rita${"title":"Disruptive technologies and manufacturing performance in South Africa: firm-level evidence","publisher":"AERC Working Paper 2022/004","year":2022,"authors":["Avenyo","Bell"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://publication.aercafricalibrary.org/handle/123456789/3444","regions":["Southern Africa"],"project":"digital-technologies-and-manufacturing-performance","authorOrderConfirmed":true,"pdf":"https://publication.aercafricalibrary.org/handle/123456789/3444","summary":"The paper tests whether adopting disruptive digital technologies improves the performance of South African manufacturing firms. It addresses a thin evidence base on technology adoption and digital skills in developing countries and discusses implications for national Fourth Industrial Revolution policy.","keyFindings":["Adoption of disruptive digital technologies matters for manufacturing firm performance."],"methods":"Econometric analysis of firm-level South African digital skills survey data.","sources":["https://publication.aercafricalibrary.org/handle/123456789/3444"]}$rita$::jsonb, 'published'),
('publications', 'do-productive-capabilities-affect-export-performance-evidence-from', $rita${"title":"Do productive capabilities affect export performance? Evidence from African firms","publisher":"European Journal of Development Research 33(2)","year":2021,"authors":["Avenyo","Tregenna","Kraemer-Mbula"],"type":"journal","programmes":["INN"],"externalUrl":"https://link.springer.com/article/10.1057/s41287-021-00364-6","regions":["Africa-wide"],"doi":"10.1057/s41287-021-00364-6","summary":"There is limited empirical evidence on productive capabilities and their effect on firm-level export performance in Africa. The paper builds indicators that treat productive capabilities as a mix of technological and production capabilities, and finds both significantly drive firms' direct export performance.","keyFindings":["Technological and production capabilities both significantly drive firms' direct export performance.","Stronger capabilities make firms more efficient and competitive, supporting policies that build them."],"methods":"World Bank Enterprise Survey data for firms in 29 African countries, estimated with a censored regression model.","sources":["https://ideas.repec.org/a/pal/eurjdr/v33y2021i2d10.1057_s41287-021-00364-6.html","https://pure.uj.ac.za/en/publications/do-productive-capabilities-affect-export-performance-evidence-fro/"]}$rita$::jsonb, 'published'),
('publications', 'domestic-ipr-protection-and-the-margins-of-bilateral-exports', $rita${"title":"Domestic intellectual property rights protection and the margins of bilateral exports","publisher":"UNU-MERIT Working Paper 2018-035","year":2018,"authors":["Ndubuisi","Foster-McGregor"],"type":"working-paper","programmes":["INN"],"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://merit.unu.edu/publications/working-papers/abstract/?id=7899","summary":"Earlier research on domestic intellectual property rights (IPR) protection and trade has looked mostly at imports. This paper turns to exports and finds that IPRs are trade-related and can help boost exports in both developed and developing countries.","keyFindings":["Stronger IPR protection can boost exports in both developed and developing countries.","IPR strength in the exporting country matters more than in the importing country.","The effect works mainly through the extensive margin; effects on the intensive margin are mostly insignificant."],"sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=7899","https://www.idos-research.de/en/others-publications/article/domestic-intellectual-property-rights-protection-and-the-margins-of-bilateral-exports/"]}$rita$::jsonb, 'published'),
('publications', 'drivers-of-services-sector-growth-acceleration-in-developing-countries', $rita${"title":"Drivers of services sector growth acceleration in developing countries","publisher":"WIDER Working Paper 2023/87","year":2023,"authors":["Ndubuisi","Owusu","Asiama","Avenyo"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://www.wider.unu.edu/publication/drivers-services-sector-growth-acceleration-developing-countries","regions":["Global"],"project":"services-sector-acceleration","authorOrderConfirmed":true,"pdf":"https://www.wider.unu.edu/sites/default/files/Publications/Working-paper/PDF/wp2023-87-drivers-services-sector-growth-acceleration-developing-countries.pdf","summary":"The services sector is dominant and still growing fast in many developing economies, yet in-depth evidence on what drives services growth accelerations is limited. This paper identifies the underlying factors, separately for market and non-market services.","keyFindings":["Several macro and institutional factors are important drivers of market services growth acceleration.","A different, heterogeneous set of drivers matters for non-market services."],"methods":"Economic Transformation Database for 50 developing countries, 1990–2018, estimated with probit models.","sources":["https://wider.unu.edu/publication/drivers-services-sector-growth-acceleration-developing-countries"]}$rita$::jsonb, 'published'),
('publications', 'economic-sentiment-and-climate-transition-during-covid-19', $rita${"title":"Economic sentiment and climate transition during the COVID-19 pandemic","publisher":"In Goutte, Guesmi and Urom (eds), Financial Market Dynamics after COVID 19, Springer, ch. 8","year":2022,"authors":["Ndubuisi","Yuni","Tingum"],"type":"book-chapter","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://www.springerprofessional.de/en/economic-sentiment-and-climate-transition-during-the-covid-19-pa/20350390","summary":"The chapter examines how a newspaper-based US economic sentiment index relates to four climate-themed financial indices after COVID-19 began. Dependence varies across time horizons and market conditions.","keyFindings":["In very poor market conditions, the strongest link is between sentiment and the green bonds index over intermediate horizons.","In normal conditions, the other climate indices show rising dependence across weekly, monthly and yearly cycles.","At the pandemic's peak, dependence under normal returns was mostly positive."],"methods":"Quantile cross-spectral approach.","sources":["https://www.idos-research.de/externe-publikationen/article/economic-sentiment-and-climate-transition-during-the-covid-19-pandemic","https://www.springerprofessional.de/en/economic-sentiment-and-climate-transition-during-the-covid-19-pa/20350390"]}$rita$::jsonb, 'published'),
('publications', 'effects-of-covid-19-on-the-labour-market-in-sub-saharan-africa', $rita${"title":"Labour market effects of COVID-19 in sub-Saharan Africa: an informality lens from Burkina Faso, Mali and Senegal","publisher":"Revue d'économie du développement 29","year":2021,"authors":["Balde","Boly","Avenyo"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.cairn.info/revue-d-economie-du-developpement-2021-1-page-43.htm","regions":["West Africa"],"authorOrderConfirmed":true,"pdf":"https://merit.unu.edu/publications/working-papers/abstract/?id=8514","summary":"Using real-time survey evidence from Burkina Faso, Mali and Senegal, the paper shows that workers in the informal economy were hit harder by the COVID-19 pandemic. Informal workers were more likely to lose their jobs, see earnings fall and struggle to meet basic needs.","keyFindings":["Informal workers were more likely to lose their jobs and see their earnings fall.","Informal workers were more likely to struggle to meet basic needs during the pandemic.","Remittances from family members helped soften the adverse effects."],"methods":"Survey of 900 individuals in Burkina Faso, Mali and Senegal, collected 20 April–1 May 2020 during lockdowns.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=8514","https://ideas.repec.org/a/cai/edddbu/edd_351_0043.html"]}$rita$::jsonb, 'published'),
('publications', 'energy-focused-sectors-and-artificial-intelligence', $rita${"title":"Quantile co-movement and dependence between energy-focused sectors and artificial intelligence","publisher":"Technological Forecasting and Social Change 183, 121842","year":2022,"authors":["Urom","Ndubuisi","Guesmi","Benkraien"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.techfore.2022.121842","externalUrl":"https://doi.org/10.1016/j.techfore.2022.121842","pdf":"https://repository.tudelft.nl/file/File_702c84e6-ec13-4ea4-abe5-c3e8f4be0cb9","summary":"The paper studies links between artificial intelligence and eight energy-focused sectors. The performance of energy-focused corporations, especially in renewable energy, depends strongly on the performance of AI.","keyFindings":["Renewable energy firms in particular are strongly tied to AI performance.","Dependence varies across energy sectors, market conditions and investment horizons.","The dependence became stronger during the first wave of the COVID-19 pandemic."],"methods":"Quantile regressions and quantile cross-spectral coherency models.","sources":["https://www.idos-research.de/en/others-publications/article/quantile-co-movement-and-dependence-between-energy-focused-sectors-and-artificial-intelligence/"]}$rita$::jsonb, 'published'),
('publications', 'escaping-corruption-in-the-demand-for-public-services-in-africa-the', $rita${"title":"Escaping corruption in the demand for public services in Africa: the dual nature of civic networks","publisher":"World Development 177, 106541","year":2024,"authors":["Osei","Konte","Avenyo"],"type":"journal","programmes":["INN"],"regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1016/j.worlddev.2024.106541","externalUrl":"https://doi.org/10.1016/j.worlddev.2024.106541","summary":"Not everyone is a victim of bribery-seeking officials: social networks serve as substitutes for, or exit options out of, corruption. But people facing multiple deprivations cannot use their networks to ease access, while those who already have access use networks to complement corrupt acts and get ahead.","keyFindings":["Social networks can act as a way out of corruption when demanding public services.","Individuals facing multiple deprivations lack access to public services because they cannot use their networks to ease access.","Those with access use social networks as complements to corrupt acts to get ahead."],"methods":"Bivariate ordered probit on the sixth wave of the Afrobarometer survey, 36 African countries, 2014–2015.","sources":["https://pure.uj.ac.za/en/publications/escaping-corruption-in-the-demand-for-public-services-in-africa-t/","https://ideas.repec.org/a/eee/wdevel/v177y2024ics0305750x24000111.html"]}$rita$::jsonb, 'published'),
('publications', 'estimating-the-effects-of-robotization-on-exports', $rita${"title":"Estimating the effects of robotization on exports","publisher":"UNU-MERIT Working Paper 2018-046","year":2018,"authors":["Ndubuisi","Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["Global"],"note":"The founders’ first joint paper.","authorOrderConfirmed":true,"externalUrl":"https://merit.unu.edu/publications/working-papers/abstract/?id=8031","pdf":"https://cris.maastrichtuniversity.nl/ws/files/309267438/fulltext","summary":"Digitalisation has drawn the attention of empirical trade economists, but robotisation largely has not. This paper examines the impact of robotisation on trade and finds that it raises total exports, on both the extensive and the intensive margin.","keyFindings":["Robotisation raises total exports through more product varieties (extensive margin) and higher average value per variety (intensive margin).","The intensive-margin effect comes from both higher quantities and higher unit prices.","Results hold when the margins are redefined as destination markets and product-destination pairs."],"methods":"Export volume and price data, decomposed into extensive and intensive margins.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=8031","https://ideas.repec.org/p/unm/unumer/2018046.html"]}$rita$::jsonb, 'published'),
('publications', 'export-variety-and-imported-intermediate-inputs-industry-level-evidence', $rita${"title":"Export variety and imported intermediate inputs: industry-level evidence from Africa","publisher":"MPRA Paper No. 106008","year":2021,"authors":["Ndubuisi","Mensah","Owusu"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://mpra.ub.uni-muenchen.de/106008/","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://mpra.ub.uni-muenchen.de/106008/1/MPRA_paper_106008.pdf","summary":"Using manufacturing industry-level data for 26 African countries, the paper finds strong evidence of a positive relationship between imported intermediate inputs and the variety of exported products. Imported inputs help because they are lower-priced and embody higher quality and technology.","keyFindings":["Imported intermediate inputs are positively related to the variety of products a country exports.","The effect works through lower prices and higher-quality, technology-embodied inputs.","The effect depends on an industry's absorptive capacity, especially when inputs come from advanced countries."],"methods":"Manufacturing industry-level panel data across 26 African countries, 1995–2016.","sources":["https://ideas.repec.org/p/pra/mprapa/106008.html","https://mpra.ub.uni-muenchen.de/106008"],"note":"First posted July 2020, revised February 2021."}$rita$::jsonb, 'published'),
('publications', 'exporters-and-gvc-participation-firm-level-evidence-from-south-africa', $rita${"title":"Exporters and global value chain participation: firm-level evidence from South Africa","publisher":"WIDER Working Paper 2020/145","year":2020,"authors":["Mazzi","Ndubuisi","Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["Southern Africa"],"project":"exporters-and-gvc-participation-in-south-africa","authorOrderConfirmed":true,"doi":"10.35188/UNU-WIDER/2020/902-0","externalUrl":"https://wider.unu.edu/publication/exporters-and-global-value-chain-participation","pdf":"https://sa-tied-archive.wider.unu.edu/sites/default/files/SA-TIED-WP-144.pdf","summary":"The study examines how global value chain (GVC) trade affects the performance of South African manufacturing exporters, comparing the productivity premium of traders across GVC-related and traditional product categories and testing for learning-by-exporting.","keyFindings":["GVC-related trade is associated with a higher productivity premium than traditional trade."],"methods":"SARS–National Treasury firm-level panel data, 2009–2017; productivity premia compared across product categories, with effects estimated before and after export market entry.","sources":["https://ideas.repec.org/p/unu/wpaper/wp-2020-145.html","https://sa-tied-archive.wider.unu.edu/article/exporters-and-global-value-chain-participation-firm-level-evidence-south-africa"]}$rita$::jsonb, 'published'),
('publications', 'fettered-cross-border-capital-flows-external-finance-dependence-and', $rita${"title":"Fettered cross-border capital flows, external finance dependence, and international trade","publisher":"International Economics 164, 206–216","year":2020,"authors":["Ndubuisi"],"type":"journal","programmes":["IND"],"externalUrl":"https://doi.org/10.1016/j.inteco.2020.10.002","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.inteco.2020.10.002","pdf":"https://mpra.ub.uni-muenchen.de/98560/","summary":"The paper evaluates how capital controls affect exports, a link that has not been thoroughly examined empirically. It uses bilateral industry-level export data for a large number of countries.","methods":"Bilateral industry-level export data across many countries; identification from variation in capital controls across countries and in external finance dependence across industries.","sources":["https://ideas.repec.org/a/eee/inteco/v164y2020icp206-216.html","https://mpra.ub.uni-muenchen.de/98560/"]}$rita$::jsonb, 'published'),
('publications', 'fibre-processing-and-manufacturing-seta-and-industry-4-0', $rita${"title":"Fibre processing & manufacturing SETA and Industry 4.0","publisher":"CCRED-IDTT Working Paper 2022/08","year":2022,"authors":["Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["Southern Africa"],"authorOrderConfirmed":true}$rita$::jsonb, 'published'),
('publications', 'financial-and-commodity-market-volatility-and-real-activity', $rita${"title":"How do financial and commodity markets volatility react to real economic activity?","publisher":"Finance Research Letters 47(B), 102733","year":2022,"authors":["Urom","Ndubuisi","Guesmi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.frl.2022.102733","externalUrl":"https://ideas.repec.org/a/eee/finlet/v47y2022ipbs1544612322000563.html","summary":"The paper tests lead-lag links and integration between real economic activity and financial and commodity market volatility. Real activity shocks co-move with these markets, but the markets led that co-movement during downturns such as the COVID-19 pandemic.","keyFindings":["Real economic activity shocks co-move with financial and commodity market volatility.","The markets led the co-movement during downturns such as COVID-19.","Connectedness is stronger during downturns and over the long run."],"methods":"Discrete wavelet analysis of lead-lag links and a time-varying parameter VAR with stochastic volatility.","sources":["https://ideas.repec.org/a/eee/finlet/v47y2022ipbs1544612322000563.html","https://www.idos-research.de/en/others-publications/article/how-do-financial-and-commodity-markets-volatility-react-to-real-economic-activity/"]}$rita$::jsonb, 'published'),
('publications', 'financial-constraints-trust-and-export-performance-firm-level-evidence', $rita${"title":"Financial constraint, trust, and export performances: firm-level evidence from Africa","publisher":"Journal of Institutional Economics 17(4), 583–605","year":2021,"authors":["Konte","Ndubuisi"],"type":"journal","programmes":["INN"],"regions":["Africa-wide"],"authorOrderConfirmed":true,"externalUrl":"https://ideas.repec.org/a/cup/jinsec/v17y2021i4p583-605_4.html","summary":"The paper examines the effect of financial constraints on exports in Africa and how the level of trust in the countries where firms are located shapes this relationship. Financial constraints reduce export activity, but the negative effect is weaker where trust is higher.","keyFindings":["Financial constraints reduce firms' export activity.","The negative effect is weaker in countries with higher trust.","Small and medium-sized firms are more exposed to financial constraints but gain more from higher trust; for larger firms only interpersonal trust matters."],"methods":"World Bank Enterprise Surveys combined with country-level measures of personal and interpersonal trust from Afrobarometer surveys in 19 African countries.","sources":["https://ideas.repec.org/a/cup/jinsec/v17y2021i4p583-605_4.html","https://www.idos-research.de/en/others-publications/article/financial-constraints-trust-and-export-performances-firm-level-evidence-from-africa/"]}$rita$::jsonb, 'published'),
('publications', 'firm-volatility-in-an-era-of-global-value-chains-the-role-of-product', $rita${"title":"Firm volatility in an era of global value chain: the role of product quality","publisher":"AERC Working Paper GVC-II-007","year":2025,"authors":["Ndubuisi","Owusu"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://publication.aercafricalibrary.org/items/9705d6c4-3a3e-4eb9-b4d7-ed909f8ebd4c","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://publication.aercafricalibrary.org/bitstreams/90480477-a89e-424e-b88e-70ca9a6d4cd5/download","summary":"More than half of global trade now runs through global value chains (GVCs), yet the literature on trade and volatility has not considered them. This paper studies how GVC participation affects the volatility of firms' job growth, and whether product quality changes that relationship.","keyFindings":["Deeper GVC embeddedness lowers firm volatility.","The effect is strongest for firms that make and export higher-quality goods.","GVC participation offers firms a route to resilience, supporting production capacity and stable export earnings."],"methods":"South African tax-authority transaction data on formal manufacturing firms, 2010–2017.","sources":["https://publication.aercafricalibrary.org/items/9705d6c4-3a3e-4eb9-b4d7-ed909f8ebd4c/full","https://ideas.repec.org/p/aer/wpaper/9705d6c4-3a3e-4eb9-b4d7-ed909f8ebd4c.html"]}$rita$::jsonb, 'published'),
('publications', 'gendering-green-transition-in-africa-implications-of-transformative', $rita${"title":"Gendering green transition in Africa: implications of transformative policies","publisher":"UNU-MERIT Working Paper 2026-011","year":2026,"authors":["Ndubuisi","Avenyo"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://cris.maastrichtuniversity.nl/en/publications/gendering-green-transition-in-africa-implications-of-transformati/","regions":["Africa-wide"],"project":"structural-change-gender-equality-acet","authorOrderConfirmed":true,"sources":["https://econpapers.repec.org/RePEc:unm:unumer:2026011","https://cris.maastrichtuniversity.nl/en/publications/gendering-green-transition-in-africa-implications-of-transformati/"]}$rita$::jsonb, 'published'),
('publications', 'gendering-structural-change-and-green-transition-in-africa-implications', $rita${"title":"Gendering structural change and green transition in Africa: implications of transformative policies","publisher":"ACET background paper, African Transformation Report 4","year":2024,"authors":["Ndubuisi","Avenyo","Chisoro"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","regions":["Africa-wide"],"project":"structural-change-gender-equality-acet","pdf":"https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","summary":"The paper examines how structural change and the green transition affect gender employment gaps in Africa. Shifts in sectoral composition have tended to widen gender employment gaps, while green energy systems and transition technologies create chances for more gender-balanced employment.","keyFindings":["Shifts in sectoral composition have tended to widen gender employment gaps.","Policies that expand women's economic opportunities and social standing offset that effect.","Green energy and transition technologies open room for gender-balanced jobs, but entrenched inequalities are a major obstacle."],"methods":"Panel data for 48 African countries, 1992–2019, with case studies of Ghana and South Africa.","sources":["https://egc.yale.edu/sites/default/files/2024-10/ACET_Gendering_Structural_Change_and_Green_Transition_in_Africa.pdf","https://cris.maastrichtuniversity.nl/en/publications/gendering-green-transition-in-africa-implications-of-transformati/","https://www.wits.ac.za/events-archive/scis/gendering-structural-change-and-green-transition-in-africa-implications-of-transformative-policies.php"]}$rita$::jsonb, 'published'),
('publications', 'geopolitical-risks-global-market-factors-and-dependence-among-regional', $rita${"title":"Geopolitical risks, global market factors and dependence among regional sustainable investments and commodities","publisher":"Quarterly Review of Economics and Finance 91, 94–111","year":2023,"authors":["Urom","Ndubuisi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.qref.2023.07.007","externalUrl":"https://doi.org/10.1016/j.qref.2023.07.007","pdf":"https://repository.tudelft.nl/file/File_5f30ab39-1255-4744-81ce-f22e3a11c2cd","summary":"The paper studies how sustainable investment indices for North America, Europe and Asia-Pacific connect with energy, precious metal and industrial metal commodities. It finds asymmetric connectedness, significantly stronger during extreme downside and upside market conditions.","keyFindings":["Total connectedness is significantly stronger during extreme market downturns and rallies.","Only the Asia-Pacific sustainable investment index receives more shocks than it transmits in normal conditions.","Geopolitical risks, business conditions, gold and fixed income markets and economic policy uncertainty predict return connectedness."],"methods":"Quantile VAR connectedness approach, with regression analysis of macro and geopolitical predictors.","sources":["https://ideas.repec.org/a/eee/quaeco/v91y2023icp94-111.html","https://repository.tudelft.nl/file/File_5f30ab39-1255-4744-81ce-f22e3a11c2cd"]}$rita$::jsonb, 'published'),
('publications', 'global-commodity-and-equity-spillovers-to-africa-during-covid-19', $rita${"title":"Global commodity and equity markets spillovers to Africa during the COVID-19 pandemic","publisher":"Emerging Markets Review 55, 100948","year":2023,"authors":["Urom","Ndubuisi","Del Lo","Yuni"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1016/j.ememar.2022.100948","externalUrl":"https://ideas.repec.org/a/eee/ememar/v55y2023ics1566014122000656.html","pdf":"https://repository.tudelft.nl/file/File_0650cf60-2bde-46e2-a6cb-78678a5aeded","summary":"The study examines connectedness between 12 African equity markets and global commodity and developed equity markets, with a focus on the peak of the COVID-19 pandemic.","keyFindings":["African equity markets are weakly connected to global markets, but connectedness rose notably during the pandemic.","Energy markets dominate shock transmission within the commodity system.","France transmits the largest equity spillover over the full sample; South Africa does so during the pandemic peak."],"sources":["https://research.tudelft.nl/en/publications/global-commodity-and-equity-markets-spillovers-to-africa-during-t","https://ideas.repec.org/a/eee/ememar/v55y2023ics1566014122000656.html"]}$rita$::jsonb, 'published'),
('publications', 'global-macroeconomic-factors-and-connectedness-among-nfts-and-un', $rita${"title":"Global macroeconomic factors and the connectedness among NFTs and (un)conventional assets","publisher":"Research in International Business and Finance 71, 102429","year":2024,"authors":["Urom","Ndubuisi","Guesmi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://ideas.repec.org/a/eee/riibaf/v71y2024ics0275531924002228.html","pdf":"https://repository.tudelft.nl/file/File_60bd20ff-042f-4cde-bf07-9369b7cea6d9?preview=1","summary":"The paper measures how returns and volatility move between NFTs and conventional and unconventional assets under different market conditions, and tests whether global macroeconomic and geopolitical indicators predict that connectedness.","keyFindings":["Connectedness varies by market condition and is strongest during extreme events.","Return connectedness generally exceeds volatility connectedness, except in bullish periods.","NFTs are largely decoupled from other assets in normal markets and become a net return-shock transmitter in bullish markets."],"methods":"Quantile-VAR connectedness approach with linear regression tests of macroeconomic and geopolitical predictors.","sources":["https://ideas.repec.org/a/eee/riibaf/v71y2024ics0275531924002228.html","https://cris.maastrichtuniversity.nl/en/publications/quantile-return-and-volatility-connectedness-among-non-fungible-t/"]}$rita$::jsonb, 'published'),
('publications', 'global-regional-and-national-mortality-among-young-people-aged-10-24', $rita${"title":"Global, regional, and national mortality among young people aged 10–24 years, 1950–2019: a systematic analysis for the Global Burden of Disease Study 2019","publisher":"The Lancet 398(10311), 1593–1618","year":2021,"authors":["GBD 2019 Adolescent Mortality Collaborators"],"type":"journal","programmes":[],"externalUrl":"https://doi.org/10.1016/S0140-6736(21)01546-4","archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/S0140-6736(21)01546-4","pdf":"https://doi.org/10.1016/S0140-6736(21)01546-4","summary":"Using GBD 2019 estimates, the study examines deaths and mortality rates among 10–24-year-olds in 204 countries and territories from 1950 to 2019. Variation in adolescent mortality between countries and by sex is widening.","keyFindings":["Differences in adolescent mortality between countries and by sex are widening.","This is driven by poor progress in reducing deaths among males and older adolescents."],"methods":"Global Burden of Disease 2019 estimates for 204 countries and territories, 1950–2019 (causes from 1980).","sources":["https://researchers.westernsydney.edu.au/en/publications/global-regional-and-national-mortality-among-young-people-aged-10/"]}$rita$::jsonb, 'published'),
('publications', 'global-value-chains-and-the-innovativeness-of-firms-in-africa', $rita${"title":"Global value chains and the innovativeness of firms in Africa","publisher":"Technovation 146, 103276","year":2025,"authors":["Ndubuisi","Mensah","Avenyo","Sakyi"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1016/j.technovation.2025.103276","doi":"10.1016/j.technovation.2025.103276","regions":["Africa-wide"],"project":"gvc-participation-and-innovation-in-africa","authorOrderConfirmed":true,"pdf":"https://repository.tudelft.nl/file/File_edea85b5-61a5-4bb5-9b12-e86d1c5db1ab","summary":"The paper tests whether participation in global value chains is linked to firm innovation in Africa. African GVC firms are highly innovative: they are more likely to introduce new products and processes, to introduce both together, and to introduce radical innovations.","keyFindings":["GVC firms are more likely to introduce product, process and radical innovations.","Integrating small, medium and younger firms into GVCs helps them overcome resource constraints and innovate more.","Innovation gains spill over to non-GVC firms in the same industry and region."],"methods":"Firm-level data from the World Bank Enterprise Surveys for African countries.","sources":["https://research.tudelft.nl/en/publications/global-value-chains-and-the-innovativeness-of-firms-in-africa/","https://ideas.repec.org/a/eee/techno/v146y2025ics0166497225001087.html"]}$rita$::jsonb, 'published'),
('publications', 'global-value-chains-job-creation-and-job-destruction-among-firms-in', $rita${"title":"Global value chains, job creation and job destruction among firms in South Africa","publisher":"STEG Working Paper WP073 (CEPR)","year":2023,"authors":["Ndubuisi","Owusu"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://cepr.org/publications/wp073","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://steg.cepr.org/sites/default/files/2023-08/WP073%20NdubuisiOwusuGlobalValueChainsJobCreation.pdf","summary":"Using data on all formal firms in South Africa, the paper finds that integration into global value chains is linked to a net gain in jobs at the firm level. The net gain is mostly driven by firms entering GVCs, while continuing GVC firms show an overall net job loss.","keyFindings":["GVC integration is associated with net job gains at the firm level.","The gain is driven by firms entering GVCs; continuing GVC firms show a net job loss.","Suggestive evidence points to a role for firm age and size."],"methods":"Firm-level panel data from the South African Revenue Service and National Treasury, with job creation and destruction measured following Haltiwanger et al. (2014).","sources":["https://steg.cepr.org/publications/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa","https://steg.cepr.org/projects/global-value-chains-job-creation-and-job-destruction-among-firms-south-africa"]}$rita$::jsonb, 'published'),
('publications', 'greening-manufacturing-technology-intensity-and-co2-emissions-in', $rita${"title":"Greening manufacturing: technology intensity and carbon dioxide emissions in developing countries","publisher":"Applied Energy 324, 119726","year":2022,"authors":["Avenyo","Tregenna"],"type":"journal","programmes":["IND"],"externalUrl":"https://doi.org/10.1016/j.apenergy.2022.119726","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.apenergy.2022.119726","summary":"The paper asks whether medium- and high-technology manufacturing industries are less emissions-intensive than low-technology ones in developing countries. It finds that medium- and high-technology industries are associated with lower CO₂ emissions, with differences that vary by countries' income levels.","keyFindings":["Medium- and high-technology manufacturing is associated with lower CO₂ emissions than low-technology manufacturing.","The differences vary with countries' income levels.","A shift towards more technology-intensive manufacturing could be one part of environmentally sustainable industrialisation."],"methods":"Panel of 68 developing and emerging economies, 1990–2016, using two emissions measures and generalised method of moments (GMM) estimation.","sources":["https://www.sciencedirect.com/science/article/pii/S0306261922010169","https://pure.uj.ac.za/en/publications/greening-manufacturing-technology-intensity-and-carbon-dioxide-em/","https://www.uj.ac.za/wp-content/uploads/2021/10/sarchi-id-pb-2023-01-avenyo-e--tregenna-f--january-2023.pdf"]}$rita$::jsonb, 'published'),
('publications', 'gvc-participation-and-innovation-firm-level-evidence-from-africa', $rita${"title":"Global value chain participation and innovation: firm-level evidence from Africa","publisher":"AERC Working Paper GVC-012","year":2022,"authors":["Avenyo","Mensah","Ndubuisi","Sakyi"],"type":"working-paper","programmes":["INN"],"regions":["Africa-wide"],"project":"gvc-participation-and-innovation-in-africa","authorOrderConfirmed":true,"externalUrl":"https://publication.aercafricalibrary.org/items/d47bb03f-a59d-4429-9b5e-d0a6c0ffb27f","pdf":"https://publication.aercafricalibrary.org/bitstreams/3b5b0cca-b1d6-42e9-85c0-8e61c74971b7/download","summary":"The paper asks whether engagement in global value chains (GVCs) is linked to the innovative capabilities of firms in Africa.","keyFindings":["Firms in Africa that engage in GVC activities are more likely to introduce innovative products onto markets.","The result holds after addressing reverse causality, and is robust to alternative definitions of GVC and innovation and to a different identification strategy."],"methods":"World Bank Enterprise Survey firm-level data.","sources":["https://publication.aercafricalibrary.org/items/d47bb03f-a59d-4429-9b5e-d0a6c0ffb27f","https://www.idos-research.de/en/others-publications/article/global-value-chain-participation-and-innovation-firm-level-evidence-from-africa/"]}$rita$::jsonb, 'published'),
('publications', 'how-important-is-gvc-participation-for-export-upgrading', $rita${"title":"How important is GVC participation for export upgrading?","publisher":"The World Economy 44(10), 2886–2907","year":2021,"authors":["Ndubuisi","Owusu"],"type":"journal","programmes":["INN"],"externalUrl":"https://onlinelibrary.wiley.com/doi/full/10.1111/twec.13102","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1111/twec.13102","pdf":"https://merit.unu.edu/publications/working-papers/abstract/?id=8528","summary":"High-quality exports need knowledge-intensive production, quality inputs and advanced technology, and global value chains are one route to them. Using product-level export data, the paper finds that participation in backward and forward GVCs raises the quality of exported products.","keyFindings":["GVC participation raises the quality of exported products.","The benefit differs by income group.","Developing countries benefit only from backward GVC participation."],"methods":"Highly disaggregated product-level export data for 122 countries.","sources":["https://research.tudelft.nl/en/publications/how-important-is-gvc-participation-to-export-upgrading/","https://merit.unu.edu/publications/working-papers/abstract/?id=8528"]}$rita$::jsonb, 'published'),
('publications', 'icts-and-employment-in-ghana-the-role-of-enterprise-formality', $rita${"title":"Revisiting the effect of information and communication technologies on employment growth in Ghana: the role of enterprise formality","publisher":"Scientific African 26, e02394","year":2024,"authors":["Fu","Avenyo"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S2468227624003363","regions":["West Africa"],"authorOrderConfirmed":true,"pdf":"https://www.oxfordtmcd.org/sites/default/files/2023-11/TMCD%20Working%20Paper%20Series%20No.%20085_0.pdf","summary":"The paper revisits how ICTs affect employment growth in Ghanaian manufacturing enterprises, across formal and informal firms. Internet access is associated with more jobs, especially in more formal firms, while informal enterprises remain small even when they use the internet.","keyFindings":["Internet access is associated with higher employment, with larger gains in more formal enterprises.","Informal enterprises appear to remain small in employment terms when using internet technology.","Adopting mobile phone technologies reduces the number of workers in enterprises."],"methods":"Feasible Generalised Least Squares regressions on repeated cross-sectional data for 483 Ghanaian manufacturing enterprises, 2013 and 2015.","sources":["https://doaj.org/article/55378e2fe0df4dfebd08ebcf968c8708","https://pure.uj.ac.za/en/publications/revisiting-the-effect-of-information-and-communication-technologi/"]}$rita$::jsonb, 'published'),
('publications', 'icts-quality-and-technical-efficiency', $rita${"title":"ICTs quality and technical efficiency: an empirical analysis","publisher":"Telecommunications Policy 46(10), 102439","year":2022,"authors":["Ndubuisi","Otioma","Owusu","Tetteh"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S0308596122001410","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.telpol.2022.102439","summary":"Earlier work on ICTs and technical efficiency relied mainly on quantity-based ICT measures, which have come under severe criticism. This paper shifts the focus to quality-based measures, in this case Internet quality, and finds a positive effect on technical efficiency.","keyFindings":["Internet quality has a positive effect on technical efficiency.","The gains are larger in countries with more skilled labour, more cross-border trade, stronger contract enforcement and deeper financial markets.","The marginal effect of ICT quality rises as the number of Internet users grows."],"sources":["https://research.tudelft.nl/en/publications/icts-quality-and-technical-efficiency-an-empirical-analysis/","https://ideas.repec.org/a/eee/telpol/v46y2022i10s0308596122001410.html"]}$rita$::jsonb, 'published'),
('publications', 'identifying-vulnerable-and-priority-manufacturing-sectors-for-economic', $rita${"title":"Identifying vulnerable and priority manufacturing sectors for economic recovery in South Africa","publisher":"CCRED-IDTT Working Paper 2021/05","year":2021,"authors":["Avenyo","Bell","Nyamwena","Robb"],"type":"working-paper","programmes":["IND"],"regions":["Southern Africa"],"authorOrderConfirmed":true,"externalUrl":"https://www.competition.org.za/s/IDTT-4_WP_Identifying_vulnerable_and_priority_manufacturing_sectors_for_economic_recovery_in_South_A.pdf","pdf":"https://www.competition.org.za/s/IDTT-4_WP_Identifying_vulnerable_and_priority_manufacturing_sectors_for_economic_recovery_in_South_A.pdf","sources":["https://www.competition.org.za/idtt-year-4"]}$rita$::jsonb, 'published'),
('publications', 'implied-volatility-indexes', $rita${"title":"Economic activity, and financial and commodity markets’ shocks: an analysis of implied volatility indexes","publisher":"International Economics 165, 51–66","year":2021,"authors":["Urom","Ndubuisi","Ozor"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.inteco.2020.11.005","externalUrl":"https://ideas.repec.org/a/eee/inteco/v165y2021icp51-66.html","summary":"The paper examines short- and long-run asymmetric interactions and causality between real economic activity and volatility shocks in stock, energy and gold markets. The relationships are asymmetric at both horizons.","keyFindings":["Positive and negative energy-market shocks both raise stock-market volatility in the long run.","The energy market is the main net transmitter of shocks; gold is a net receiver.","There is feedback between economic activity and the volatility indexes, except for gold, which causes economic activity in one direction only."],"methods":"Nonlinear ARDL cointegration and Granger causality tests, with Diebold–Yilmaz spillover indexes on partial-sum decompositions.","sources":["https://ideas.repec.org/a/eee/inteco/v165y2021icp51-66.html","https://cepii.fr/CEPII/fr/publications/journal_articles.asp?offset=170"]}$rita$::jsonb, 'published'),
('publications', 'import-penetration-and-manufacturing-employment-evidence-from-africa', $rita${"title":"Import penetration and manufacturing employment: evidence from Africa","publisher":"UNU-MERIT Working Paper 2022-007","year":2022,"authors":["Owusu","Ndubuisi","Mensah"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://merit.unu.edu/publications/working-papers/abstract/?id=9242","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://unu-merit.nl/publications/wppdf/2022/wp2022-007.pdf","summary":"Cross-country evidence on the labour market effects of import penetration in Africa is scarce. This paper studies how imports of intermediate and final goods affect manufacturing employment across African countries.","keyFindings":["Intermediate-good import penetration raises manufacturing employment, while final-good import penetration has a negative or, at best, insignificant effect.","Intermediate imports from developed countries increase employment, while those from developing countries reduce it."],"methods":"Manufacturing industry and establishment-level data from 20 African countries.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=9242","https://ideas.repec.org/p/unm/unumer/2022007.html"]}$rita$::jsonb, 'published'),
('publications', 'industrial-diagnostic-study', $rita${"title":"Industrial diagnostic study","publisher":"UNIDO","year":2023,"authors":["Ndubuisi"],"type":"report","programmes":["IND"],"externalUrl":"https://www.unido.org/sites/default/files/unido-publications/2024-02/Industrial%20diagnostic%20study_2023_0.pdf"}$rita$::jsonb, 'published'),
('publications', 'industrial-policy-the-manufacturing-sector-and-black-empowerment-in', $rita${"title":"Industrial policy, the manufacturing sector and black empowerment in South Africa","publisher":"Transformation: Critical Perspectives on Southern Africa 109, 80–111","year":2022,"authors":["Goga","Avenyo"],"type":"journal","programmes":["IND"],"externalUrl":"https://muse.jhu.edu/article/871140","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://wiredspace.wits.ac.za/items/17f7e012-82c1-4140-8a20-a29d849e81a8","summary":"Black Economic Empowerment has been an ambitious project, but results in key sectors have fallen short. The paper asks why South Africa has not seen the emergence of a large, economically significant black industrialist class, and whether industrial policy has helped or undermined deep transformation.","keyFindings":["Results of BEE in key sectors, including manufacturing, have fallen short.","The paper identifies key limitations of BEE and of the industrial policy framework.","It considers how industrial transformation could be accelerated."],"methods":"Policy analysis of the interaction between BEE and industrial policy in South African manufacturing.","sources":["https://wiredspace.wits.ac.za/items/17f7e012-82c1-4140-8a20-a29d849e81a8","https://muse.jhu.edu/article/871140"]}$rita$::jsonb, 'published'),
('publications', 'informal-innovations-in-urban-ghana-data-set-and-descriptive-analysis', $rita${"title":"Informal sector innovation in Ghana: data set and descriptive analysis","publisher":"UNU-MERIT Working Paper 2018-030","year":2018,"authors":["Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["West Africa"],"authorOrderConfirmed":true,"externalUrl":"https://merit.unu.edu/publications/working-papers/abstract/?id=7864","pdf":"https://unu-merit.nl/publications/wppdf/2018/wp2018-030.pdf","summary":"The paper presents descriptive statistics from a 2016 survey of the innovations informal firms adopt or adapt in Accra and Tema. It finds that informal enterprises do innovate: their innovations are incremental rather than radical, occur over several years, and matter for their survival.","keyFindings":["Informal enterprises do innovate.","Their innovations are incremental, not radical, and occur over several years.","Incremental innovations are important to the survival of the sampled informal enterprises."],"methods":"2016 survey of 513 informal enterprises in 17 randomly selected zones of Accra and Tema, using the World Bank Ghana Informal Enterprise Survey zones as the area frame.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=7864","https://ideas.repec.org/p/unm/unumer/2018030.html"]}$rita$::jsonb, 'published'),
('publications', 'innovation-and-performance-of-informal-enterprises-a-gender-perspective', $rita${"title":"Innovation and the performance of informal enterprises in developing countries: a gender perspective","publisher":"International Journal of Gender and Entrepreneurship 13(4), 277–301","year":2021,"authors":["Avenyo","Kraemer-Mbula"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1108/IJGE-11-2020-0174","doi":"10.1108/IJGE-11-2020-0174","regions":["West Africa"],"authorOrderConfirmed":true,"summary":"The study looks at product innovation in informal enterprises to understand how it affects employment in female- and male-owned firms. Product innovation has beneficial effects on job creation, and the authors conclude that innovation is gendered and needs a gendered policy lens.","keyFindings":["Product innovation has beneficial effects on job creation in informal enterprises.","There are no systematic differences in the factors affecting product innovation in female- and male-owned enterprises.","Female-owned enterprises are less likely to introduce product innovations, but they sell more innovative products."],"methods":"Unique data on 513 informal enterprises in Accra and Tema, Ghana, 2013–2015, analysed with a dose-response model.","sources":["https://pure.uj.ac.za/en/publications/innovation-and-the-performance-of-informal-enterprises-in-develop/","https://www.emerald.com/insight/content/doi/10.1108/IJGE-11-2020-0174/full/html"]}$rita$::jsonb, 'published'),
('publications', 'jobs-investments-and-exporting-the-real-effects-of-electricity-crises', $rita${"title":"Jobs, investments, and exporting: the real effects of electricity crisis in South Africa","publisher":"Energy Economics 157, 109234","year":2026,"authors":["Ndubuisi","Avenyo"],"type":"journal","programmes":["EN"],"externalUrl":"https://doi.org/10.1016/j.eneco.2026.109234","doi":"10.1016/j.eneco.2026.109234","regions":["Southern Africa"],"project":"electricity-crises-in-south-africa","note":"An earlier version appeared as WIDER Working Paper 2024/89.","summary":"How South Africa's electricity crises affected manufacturers' jobs, investment and exports, and what that means for an industrial strategy built on a greener grid.","authorOrderConfirmed":true,"pdf":"https://repository.tudelft.nl/file/File_2c5d23b2-81b6-465e-b966-0b0696134767","keyFindings":["The electricity crises destroyed jobs, lowered capital investment and disrupted exports of manufacturing firms.","The adverse effects are most severe for firms in sectors with higher energy vulnerability.","Ownership structure, firm age and financial status shape how much firms are affected."],"methods":"Generalised difference-in-differences exploiting sectoral differences in exposure to the electricity crisis (earlier version: WIDER Working Paper 2024/89).","sources":["https://pure.uj.ac.za/en/publications/jobs-investments-and-exporting-the-real-effects-of-electricity-cr/","https://wider.unu.edu/publication/jobs-investments-and-exporting-real-effects-electricity-crises-south-africa"]}$rita$::jsonb, 'published'),
('publications', 'learning-and-product-innovation-in-informal-enterprises-urban-ghana', $rita${"title":"Learning and product innovation performance in informal enterprises: evidence from urban Ghana","publisher":"MPRA Paper 108839","year":2021,"authors":["Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["West Africa"],"authorOrderConfirmed":true,"externalUrl":"https://mpra.ub.uni-muenchen.de/108839/","pdf":"https://mpra.ub.uni-muenchen.de/108839/7/MPRA_paper_108839.pdf","summary":"The paper examines how learning shapes product innovation in informal enterprises in urban Ghana. Apprenticeship enhances the technological capability of enterprises, leading to product innovativeness, and competitive interactions with formal firms provide market feedback that enhances innovation.","keyFindings":["Apprenticeship enhances technological capability and product innovativeness.","Competitive formal interactions provide market feedback that enhances innovativeness.","Financially constrained enterprises competing with formal firms performed poorly with their new products."],"methods":"Survey data on 513 informal enterprises in urban Ghana, estimated with a Type II Tobit model.","sources":["https://mpra.ub.uni-muenchen.de/108839/","https://ideas.repec.org/p/pra/mprapa/108839.html"],"note":"Later published in Scientific African 20 (2023)."}$rita$::jsonb, 'published'),
('publications', 'learning-by-exporting-in-south-africa-gvc-participation-and', $rita${"title":"Learning-by-exporting in South Africa: the influence of global value chain (GVC) participation and technological capability","publisher":"African Journal of Science, Technology, Innovation and Development 16(4), 459–476","year":2024,"authors":["Mazzi","Ndubuisi","Avenyo"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1080/20421338.2023.2295631","doi":"10.1080/20421338.2023.2295631","regions":["Southern Africa"],"project":"exporters-and-gvc-participation-in-south-africa","authorOrderConfirmed":true,"pdf":"https://sa-tied-archive.wider.unu.edu/sites/default/files/SA-TIED-WP-144.pdf","summary":"The paper examines how trade related to global value chains affects the performance of manufacturing firms in South Africa. GVC-related trade carries a higher productivity premium than traditional trade, but only firms that also invest in R&D appear to learn from exporting.","keyFindings":["GVC-related trade is associated with a higher productivity premium than traditional trade.","Only firms trading in GVC-related products that also engage in R&D after entry appear to learn from exporting.","GVC-integrated firms need to invest in building technological capacity."],"methods":"Firm-level panel data from SARS and National Treasury, 2009–2017, comparing productivity premia across product classifications before and after export entry.","sources":["https://ideas.repec.org/a/taf/rajsxx/v16y2024i4p459-476.html","https://pure.uj.ac.za/en/publications/learning-by-exporting-in-south-africa-the-influence-of-global-val/"]}$rita$::jsonb, 'published'),
('publications', 'learning-to-export-and-learning-by-exporting-innovation-and-exports-in', $rita${"title":"‘Learning to export’ and ‘learning by exporting’: revisiting the relationship between innovation and exports in African firms","publisher":"African Development Review 37(1)","year":2025,"authors":["Avenyo","Tregenna"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1111/1467-8268.70001","doi":"10.1111/1467-8268.70001","regions":["Africa-wide"],"authorOrderConfirmed":true,"summary":"The paper revisits the relationship between innovation and exports in African firms and finds a positive link running both ways. Innovation affects both whether a firm exports and how much it exports, and exporting makes innovation more likely.","keyFindings":["Innovation raises both the likelihood and the intensity of exporting.","Exporting raises the likelihood of innovating; effects are mostly driven by direct exports and hold for product and process innovation.","Foreign ownership and international quality certification strengthen these effects."],"methods":"Cross-sectional World Bank Enterprise Survey data for 28 African economies, estimated with a censored Tobit IV simultaneous model with selection.","sources":["https://ideas.repec.org/a/bla/afrdev/v37y2025i1ne70001.html","https://pure.uj.ac.za/en/publications/learning-to-export-and-learning-by-exporting-revisiting-the-relat/"]}$rita$::jsonb, 'published'),
('publications', 'learning-to-innovate-in-urban-informal-enterprises-of-ghana', $rita${"title":"Learning to innovate in urban informal enterprises of Ghana: role of apprenticeship and formal interaction","publisher":"Scientific African 20, e01740","year":2023,"authors":["Avenyo"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S2468227623001965","regions":["West Africa"],"authorOrderConfirmed":true,"pdf":"https://mpra.ub.uni-muenchen.de/108839/7/MPRA_paper_108839.pdf","summary":"The study looks at how two learning routes, apprenticeship and formal interactions, affect the product innovativeness of informal firms in Ghana. Apprenticeship builds technological capability that leads to product innovativeness, while competitive formal interactions supply market feedback that improves it.","keyFindings":["Apprenticeship builds technological capability that leads to product innovativeness.","Competitive interactions with formal firms provide market feedback that improves innovativeness.","Financially constrained informal enterprises competing with formal firms in product markets performed poorly with new products."],"methods":"Survey data on 513 urban informal enterprises in Ghana, estimated with a Type II Tobit model.","sources":["https://doaj.org/article/cc4c67737e484e9bbc1d6bd423f3471f","https://pure.uj.ac.za/en/publications/learning-to-innovate-in-urban-informal-enterprises-of-ghana-role-/"]}$rita$::jsonb, 'published'),
('publications', 'localisation-in-south-africa-analysis-of-key-emerging-issues', $rita${"title":"Localisation in South Africa: analysis of key emerging issues","publisher":"CCRED Working Paper Series 2023/01","year":2023,"authors":["Avenyo","Bosiu","Nyamwena"],"type":"working-paper","programmes":["IND"],"regions":["Southern Africa"],"authorOrderConfirmed":true,"externalUrl":"https://competition.org.za/working-papers","sources":["https://competition.org.za/working-papers","https://www.competition.org.za/idtt-year-6"]}$rita$::jsonb, 'published'),
('publications', 'navigating-the-eu-green-deal-in-at-risk-agro-food-sectors-in-south', $rita${"title":"Navigating the EU Green Deal in at-risk agro-food sectors in South Africa: citrus and wine","publisher":"CCRED Working Paper 2023/02","year":2023,"authors":["Bell","Goga","Muzyamba","Nyamwena","Avenyo"],"type":"working-paper","programmes":["IND"],"externalUrl":"https://www.competition.org.za/s/TIPS-EGD-WP-August-2023.pdf","regions":["Southern Africa"],"authorOrderConfirmed":true,"pdf":"https://www.competition.org.za/s/TIPS-EGD-WP-August-2023.pdf","sources":["https://www.competition.org.za/s/TIPS-EGD-WP-August-2023.pdf"]}$rita$::jsonb, 'published'),
('publications', 'nft-volume-and-returns', $rita${"title":"Dynamic dependence and predictability between volume and return of non-fungible tokens (NFTs): the roles of market factors and geopolitical risks","publisher":"Finance Research Letters 50, 103188","year":2022,"authors":["Urom","Ndubuisi","Guesmi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.frl.2022.103188","externalUrl":"https://doi.org/10.1016/j.frl.2022.103188","pdf":"https://cris.maastrichtuniversity.nl/files/106571525/wp2022_017.pdf","summary":"The paper studies the volume–return relationship for the overall NFT market and three sub-markets (Cryptokitties, Cryptopunks and Decentraland). It finds significant dependence between NFT return and volume, weakest for Cryptopunks.","keyFindings":["NFT returns and trading volume show significant dependence, weakest for Cryptopunks.","Under extreme market conditions, uncertainty in equity, gold and oil markets, business conditions and geopolitical risks predict returns, varying by sub-market.","Increases in Bitcoin prices reduce NFT market returns in all cases."],"methods":"Quantile cross-spectral coherency and quantile regression.","sources":["https://ideas.repec.org/a/eee/finlet/v50y2022ics1544612322003889.html","https://research.tudelft.nl/en/publications/dynamic-dependence-and-predictability-between-volume-and-return-o"]}$rita$::jsonb, 'published'),
('publications', 'on-gender-and-spatial-gaps-in-africas-informal-sector-evidence-from', $rita${"title":"On gender and spatial gaps in Africa’s informal sector: evidence from urban Ghana","publisher":"Economics Letters 199, 109732","year":2021,"authors":["Zinyemba","Avenyo","Francois"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/pii/S0165176521000094","regions":["West Africa"],"authorOrderConfirmed":true,"summary":"Using 2016 survey data from Accra and Tema, the paper finds an unexplained spatial gap in sales between informal enterprise owners in the two cities. There are no gender gaps in sales or innovation, but there are gender gaps in how past sales affect current sales.","keyFindings":["There is an unexplained spatial gap in sales between informal enterprises in Accra and Tema.","There are no gender gaps in sales or innovation.","Explained and unexplained gender gaps exist in the effect of past sales on current sales."],"methods":"2016 survey data on informal enterprises in Accra and Tema, Ghana.","sources":["https://ideas.repec.org/a/eee/ecolet/v199y2021ics0165176521000094.html","https://cris.maastrichtuniversity.nl/en/publications/on-gender-and-spatial-gaps-in-africas-informal-sector-evidence-fr/"]}$rita$::jsonb, 'published'),
('publications', 'patent-enforcement-and-the-quality-upgrading-of-exported-products', $rita${"title":"Patent enforcement and quality upgrading of exported products","publisher":"Journal of the Knowledge Economy 15, 13979–14011","year":2024,"authors":["Ndubuisi"],"type":"journal","programmes":["INN"],"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1007/s13132-023-01660-8","externalUrl":"https://ideas.repec.org/a/spr/jknowl/v15y2024i3d10.1007_s13132-023-01660-8.html","summary":"The paper evaluates how patent protection affects the quality of exported products across 43 advanced and emerging economies. R&D-intensive industries in countries with stronger patent protection produce and export higher-quality goods at a greater rate than similar industries in weaker-protection countries.","keyFindings":["R&D-intensive industries in countries with stronger patent enforcement upgrade export quality faster.","The effect is larger for differentiated products and in developed or more technologically capable countries.","Patent policy should account for country-specific conditions."],"methods":"Cross-country differences in patent enforcement combined with cross-industry differences in R&D intensity, for 43 advanced and emerging economies.","sources":["https://ideas.repec.org/a/spr/jknowl/v15y2024i3d10.1007_s13132-023-01660-8.html","https://www.idos-research.de/en/others-publications/article/patent-enforcement-and-quality-upgrading-of-exported-products"]}$rita$::jsonb, 'published'),
('publications', 'pgp-for-portfolio-optimization-esg-index-family', $rita${"title":"PGP for portfolio optimization: application to ESG index family","publisher":"Annals of Operations Research 347(1), 405–417","year":2025,"authors":["Abid","Urom","Peillex","Karmani","Ndubuisi"],"type":"journal","programmes":["IND"],"archive":true,"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1007/s10479-023-05460-w","externalUrl":"https://ideas.repec.org/a/spr/annopr/v347y2025i1d10.1007_s10479-023-05460-w.html","summary":"Conventional portfolio design assumes Gaussian returns, but asymmetric and heavy-tailed returns call for higher-order moments. The paper proposes a mean-variance-skewness-kurtosis model, optimised with parametrised polynomial goal programming (PGP), to build diversified portfolios.","keyFindings":["PGP generates multiple portfolios that reflect investors' different preferences over the four moments.","Portfolios are compared through the empirical cumulative distribution of returns to help investors choose a weight set."],"methods":"Mean-variance-skewness-kurtosis optimisation with polynomial goal programming, applied to the S&P ESG index family.","sources":["https://ideas.repec.org/a/spr/annopr/v347y2025i1d10.1007_s10479-023-05460-w.html"]}$rita$::jsonb, 'published'),
('publications', 'product-innovations-and-informal-market-competition-in-sub-saharan', $rita${"title":"Product innovation and informal market competition in sub-Saharan Africa","publisher":"Journal of Evolutionary Economics 31, 605–637","year":2021,"authors":["Avenyo","Konte","Mohnen"],"type":"journal","programmes":["INN"],"externalUrl":"https://doi.org/10.1007/s00191-020-00688-2","regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1007/s00191-020-00688-2","summary":"Competition from informal enterprises is one of the top three obstacles formal businesses face in sub-Saharan Africa. The paper finds that local informal competition harms the performance of product innovation, but only for formal firms that lack strategic collaborative footholds in the informal economy.","keyFindings":["Local informal competition has a robust negative effect on the product innovation intensity of formal firms.","Informal competition within an industry enhances innovative sales.","Larger firms are less affected by local informal competition and gain innovative sales from it."],"methods":"World Bank Enterprise Surveys combined with the Innovation Follow-up Survey for five sub-Saharan African countries, with regional and industry-specific indicators of informal competition.","sources":["https://ideas.repec.org/a/spr/joevec/v31y2021i2d10.1007_s00191-020-00688-2.html","https://pure.uj.ac.za/en/publications/product-innovation-and-informal-market-competition-in-sub-saharan/","https://gov.uk/research-for-development-outputs/product-innovation-and-informal-market-competition-in-sub-saharan-africa-firm-level-evidence"]}$rita$::jsonb, 'published'),
('publications', 'regionalizing-green-transition-minerals-for-structural-transformation', $rita${"title":"Regionalizing green transition minerals for structural transformation in Africa","publisher":"World Bank Group, Office of the Chief Economist for the Africa Region","year":2025,"authors":["Ndubuisi","Avenyo","Owusu","Kassa"],"type":"report","programmes":["MIN"],"externalUrl":"https://documents.worldbank.org/en/publication/documents-reports/documentdetail/099620011192519026","featured":true,"regions":["Africa-wide"],"project":"regionalizing-green-transition-minerals","authorOrderConfirmed":true,"summary":"Africa is rich in transition minerals but still exports most of them raw, which limits how much value the continent keeps. The report argues that regional cooperation, shared infrastructure and coordinated policy are needed to turn mineral wealth into regional value chains and broad prosperity.","pdf":"https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","keyFindings":["Most of Africa's transition minerals are exported raw, with weak local processing.","Exports rely heavily on Asian buyers, mainly China.","No single country holds every input; regional coordination is needed to build value chains."],"sources":["https://documents1.worldbank.org/curated/en/099620011192519026/pdf/IDU-959b6025-1de2-4caf-98be-9c8aa42577da.pdf","https://www.downtoearth.org.in/africa/africas-mineral-strength-is-wasted-if-countries-dont-work-together-new-report"]}$rita$::jsonb, 'published'),
('publications', 'remittance-dependence-support-for-taxation-and-quality-of-public', $rita${"title":"Remittance dependence, support for taxation and quality of public services in Africa","publisher":"Journal of Institutional Economics 20, e7","year":2024,"authors":["Konte","Ndubuisi"],"type":"journal","programmes":["IND"],"regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1017/S1744137423000322","externalUrl":"https://doi.org/10.1017/S1744137423000322","pdf":"https://merit.unu.edu/publications/working-papers/abstract/?id=9310","summary":"The paper asks whether depending on remittances weakens citizens' support for taxation in Africa. For about two-thirds of citizens there is no significant effect, but for the remaining third remittance dependence significantly reduces support for taxation.","keyFindings":["For the majority of citizens, remittance dependence has no significant effect on support for taxation.","For about one-third of citizens, remittance dependence significantly reduces support for taxation.","Citizens who rate public services positively are less likely to be in that group, so efficient public services may offset the effect."],"methods":"Afrobarometer round 7 data for about 45,000 respondents in 34 African countries, using a finite multilevel mixture of regressions.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=9310","https://cris.maastrichtuniversity.nl/en/publications/remittance-dependence-support-for-taxation-and-quality-of-public--2/"]}$rita$::jsonb, 'published'),
('publications', 'remittances-and-bribery-in-africa', $rita${"title":"Remittances and bribery in Africa","publisher":"In Konte and Mbaye (eds), Migration, Remittances, and Sustainable Development in Africa, Routledge, ch. 10, 179–198","year":2020,"authors":["Konte","Ndubuisi"],"type":"book-chapter","programmes":["IND"],"regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.4324/9780429288814-13","externalUrl":"https://doi.org/10.4324/9780429288814-13","pdf":"https://cris.maastrichtuniversity.nl/files/91103428/Konte_2020_Remittances_and_bribery.pdf","summary":"Using Afrobarometer surveys, the chapter finds that remittance receivers are more prone to bribe payment than non-receivers. Individuals in countries with higher remittances as a share of GDP are also more likely to pay bribes, in line with an income channel.","keyFindings":["Remittance receivers are more prone to paying bribes than non-receivers.","People in countries with higher remittances as a share of GDP are more likely to pay bribes."],"methods":"Afrobarometer survey data for African countries.","sources":["https://idos-research.de/en/others-publications/article/remittance-and-bribery-in-africa","https://merit.unu.edu/publications/working-papers/abstract/?id=8367"]}$rita$::jsonb, 'published'),
('publications', 'renewable-energy-consumption-globalization-and-economic-growth-shocks', $rita${"title":"Renewable energy consumption, globalization, and economic growth shocks: evidence from G7 countries","publisher":"Journal of International Trade & Economic Development 31(2), 204–232","year":2022,"authors":["Urom","Abid","Guesmi","Ndubuisi"],"type":"journal","programmes":["EN"],"externalUrl":"https://www.tandfonline.com/doi/full/10.1080/09638199.2021.1961845","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1080/09638199.2021.1961845","summary":"The paper examines asymmetric responses of renewable energy consumption to globalisation and economic growth shocks across the G7. Responses differ by country, but renewable energy deployment in the G7 is mainly driven by positive shocks to income, globalisation and capital.","keyFindings":["Positive globalisation shocks raise renewable energy use in Canada, Germany, the UK and the US, and negative shocks lower it.","Responses to income shocks differ across countries.","Panel results suggest renewable energy deployment is mainly driven by positive shocks to income, globalisation and capital."],"methods":"Nonlinear ARDL (NARDL) models by country, plus panel cointegration, FMOLS and panel DOLS estimates for the G7.","sources":["https://ideas.repec.org/a/taf/jitecd/v31y2022i2p204-232.html","https://cris.maastrichtuniversity.nl/en/publications/renewable-energy-consumption-globalization-and-economic-growth-sh/"]}$rita$::jsonb, 'published'),
('publications', 'solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage', $rita${"title":"Solar photovoltaic manufacturing in Africa: opportunity or mirage?","publisher":"Africa Policy Research Institute (APRI), Green & Transition Minerals Collection","year":2024,"authors":["Ndubuisi","Avenyo"],"type":"policy-paper","programmes":["EN"],"externalUrl":"https://afripoli.org/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","regions":["Africa-wide"],"project":"solar-pv-value-chain-in-africa","authorOrderConfirmed":true,"pdf":"https://afripoli.org/view-pdf/26/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","summary":"Africa holds key minerals for solar PV production, such as copper, tin and silicon, but most countries on their own lack the finance, technological capabilities and infrastructure to build a competitive PV manufacturing sector. The paper finds only scattered opportunities for local manufacturing and recommends a regionalised PV strategy to integrate into the global solar value chain.","keyFindings":["Opportunities for local solar PV manufacturing within African countries are scattered.","Entering the global value chain is hard given market concentration, high entry barriers and established players, with China dominant in nearly every segment.","Without a coordinated regional approach, individual countries are unlikely to integrate into the global market."],"sources":["https://afripoli.org/solar-photovoltaic-manufacturing-in-africa-opportunity-or-mirage","https://www.pv-magazine.com/?p=38575"]}$rita$::jsonb, 'published'),
('publications', 'solid-mineral-development-in-nigeria-evidence-from-ebonyi-ekiti-and', $rita${"title":"Solid mineral development in Nigeria: evidence from Ebonyi, Ekiti and Taraba states","publisher":"Centre LSD","year":null,"authors":["Ndubuisi"],"type":"report","programmes":["MIN"],"externalUrl":"https://centrelsd.org/news-and-updates/publications/solid-mineral-development-in-nigeria-evidence-from-ebonyi-ekiti-and-taraba-states","regions":["West Africa"],"authorOrderConfirmed":true}$rita$::jsonb, 'published'),
('publications', 'state-of-the-chemical-industry-an-industry-4-0-perspective', $rita${"title":"State of the chemical industry: an Industry 4.0 perspective","publisher":"CCRED-IDTT Working Paper 2022/07","year":2022,"authors":["Avenyo"],"type":"working-paper","programmes":["INN"],"regions":["Southern Africa"]}$rita$::jsonb, 'published'),
('publications', 'structural-change-in-africa-the-role-of-north-south-and-south-south', $rita${"title":"Structural change in Africa: the role of North-South and South-South trade","publisher":"The World Economy 49(3), 539–569","year":2026,"authors":["Ndubuisi","Owusu","Kassa"],"type":"journal","programmes":["IND"],"externalUrl":"https://doi.org/10.1111/twec.70049","regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1111/twec.70049","pdf":"https://repository.tudelft.nl/file/File_ace36a6a-4063-48a5-9563-a56b3dfd2b7e","summary":"The paper examines how imported capital and intermediate inputs from the Global North and the Global South affect structural change in African economies, and how domestic absorptive capacity moderates those effects.","keyFindings":["Inputs from the Global South have a positive effect on structural change, partly because they fit the technological realities of African economies.","Inputs from the Global North deliver benefits only where domestic absorptive capacity is high."],"methods":"Two-stage least squares on a panel of 52 African countries, 2000–2022.","sources":["https://www.bu.edu/pardeeschool/?p=62972","https://econpapers.repec.org/paper/wbkwbrwps/10896.htm"]}$rita$::jsonb, 'published'),
('publications', 'sub-saharan-africas-prospect-of-economic-development-through-global', $rita${"title":"Sub-Saharan Africa’s prospect of economic development through global supply chains","publisher":"Sustainable Global Supply Chains Report 2022, German Development Institute (DIE/IDOS), special section, p. 126","year":2022,"authors":["Ndubuisi","Owusu"],"type":"book-chapter","programmes":["IND"],"externalUrl":"https://www.oxfordmartin.ox.ac.uk/publications/sub-saharan-africas-prospect-of-economic-development-through-global-supply-chains","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://www.die-gdi.de/fileadmin/user_upload/pdfs/projekt/20220407_SustainableGlobalSupplyChains-Report2022_lowres.pdf","summary":"The chapter discusses the prospects of a global supply chain-led development strategy for Africa amid four megatrends, to identify research gaps. Global supply chains remain an important vehicle for Africa's development, but the megatrends have profound implications for that prospect.","keyFindings":["Four megatrends shape Africa's supply-chain prospects: China's rise and shift to knowledge-intensive sectors, digital transformation, African regional integration, and environmental sustainability.","Global supply chains remain important as a vehicle for economic development in Africa."],"sources":["https://www.oxfordmartin.ox.ac.uk/publications/sub-saharan-africas-prospect-of-economic-development-through-global-supply-chains"]}$rita$::jsonb, 'published'),
('publications', 'taking-stock-of-africas-economic-transformation-rethinking-sources-of', $rita${"title":"Taking stock of Africa’s economic transformation: rethinking sources of productivity growth","publisher":"The World Bank Research Observer (advance article)","year":2026,"authors":["Gollin","McMillan","Mensah","Ndubuisi","Owusu"],"type":"journal","programmes":["IND"],"regions":["Africa-wide"],"authorOrderConfirmed":true,"doi":"10.1093/wbro/lkag001","externalUrl":"https://doi.org/10.1093/wbro/lkag001","pdf":"https://thedocs.worldbank.org/en/doc/eac0289cfc530efb6dcc781f69fecd28-0050012026/original/Takingstock-EBMensah-13.pdf","summary":"Recent structural change in Africa has boosted growth, but overall labour productivity growth remains modest. Manufacturing has played a limited role since the 1990s, while services, especially wholesale and retail trade, have driven the gains.","keyFindings":["Structural change has contributed to growth, but productivity growth remains modest.","Since the 1990s, services, especially wholesale and retail trade, have driven productivity gains more than manufacturing.","Weak productivity growth reflects constraints such as limited infrastructure, extreme poverty, poor health and inadequate education."],"sources":["https://academic.oup.com/wbro/advance-article-abstract/doi/10.1093/wbro/lkag001/8586411","https://www.bu.edu/pardeeschool/tag/african-economics/"]}$rita$::jsonb, 'published'),
('publications', 'technology-capability-and-industrialization-in-africa', $rita${"title":"Technological capability and industrialization in Africa","publisher":"SARChI Industrial Development Working Paper 2024-03","year":2024,"authors":["Mensah","Ndubuisi"],"type":"working-paper","programmes":["INN"],"externalUrl":"https://aec.afdb.org/en/papers/technological-capability-and-industrialization-africa-711","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://uj.ac.za/wp-content/uploads/2021/10/sarchi-wp2024-03-mensahlj-ndubuisi-technological-capability-17032024-correct-isbn.pdf","summary":"The paper examines the spatial dynamics of technological capability in Africa and its interdependence with industrial development, using a framework that measures capability along four dimensions: technology precondition, technology infrastructure, technology import and technology effort.","keyFindings":["Levels of technological capability differ strongly across African countries.","Technological capability and industrial development are interdependent across countries.","This interdependence is propagated through intra-African regional trade."],"methods":"Composite technological capability index for African countries with spatial analysis.","sources":["https://aec.afdb.org/fr/papers/technological-capability-and-industrialization-africa-711","https://uj.ac.za/wp-content/uploads/2021/10/sarchi-wp2024-03-mensahlj-ndubuisi-technological-capability-17032024-correct-isbn.pdf"]}$rita$::jsonb, 'published'),
('publications', 'technology-intensity-in-manufacturing-and-co2-emissions', $rita${"title":"The effects of technology intensity in manufacturing on CO2 emissions: evidence from developing countries","publisher":"ERSA Working Paper 846","year":2021,"authors":["Avenyo","Tregenna"],"type":"working-paper","programmes":["IND"],"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://econrsa.org/publications/the-effects-of-technology-intensity-in-manufacturing-on-co2-emissions-evidence-from-developing-countries/","pdf":"https://econrsa.org/publications/the-effects-of-technology-intensity-in-manufacturing-on-co2-emissions-evidence-from-developing-countries/","summary":"The paper asks whether high-technology manufacturing emits less CO2 than medium- and low-technology manufacturing in developing economies. It concludes that a shift towards more technology-intensive manufacturing could be a more sustainable industrialisation path.","keyFindings":["In exports, high-technology manufacturing is linked to lower emissions than medium- and low-technology exports.","A shift towards more technology-intensive manufacturing could be a more sustainable industrialisation path."],"methods":"Panel of 56 developing economies, 1991–2014, combining the environmental Kuznets curve and STIRPAT frameworks, estimated with GMM.","sources":["https://econpapers.repec.org/RePEc:rza:ersawp:846","https://econrsa.org/publications/the-effects-of-technology-intensity-in-manufacturing-on-co2-emissions-evidence-from-developing-countries/"],"note":"Revised and published as ‘Greening manufacturing’, Applied Energy 324 (2022)."}$rita$::jsonb, 'published'),
('publications', 'the-employment-impact-of-product-innovations-in-sub-saharan-africa', $rita${"title":"The employment impact of product innovations in sub-Saharan Africa: firm-level evidence","publisher":"Research Policy 48(9), 103806","year":2019,"authors":["Avenyo","Konte","Mohnen"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.sciencedirect.com/science/article/abs/pii/S004873331930126X","regions":["Africa-wide"],"authorOrderConfirmed":true,"pdf":"https://merit.unu.edu/publications/working-papers/abstract/?id=8268","summary":"The paper investigates the impact of product innovations on job creation in sub-Saharan African firms. Product innovations raise total employment, but only at specific intervals of innovation intensity, and the gains are larger for temporary and unskilled jobs.","keyFindings":["Product innovations have a positive impact on total employment, but only at specific intervals of innovation intensity.","Product innovations create both temporary and permanent, and skilled and unskilled, jobs.","Larger gains for temporary and unskilled jobs raise questions about the security and quality of new jobs."],"methods":"Dose-response model on recent waves of the World Bank Enterprise Survey merged with the Innovation Follow-Up Survey.","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=8268","https://cris.maastrichtuniversity.nl/en/publications/the-employment-impact-of-product-innovations-in-sub-saharan-afric"]}$rita$::jsonb, 'published'),
('publications', 'the-future-of-industrialization-in-sub-saharan-africa-bottlenecks-and', $rita${"title":"The future of industrialization in sub-Saharan Africa: bottlenecks and sectoral opportunities","publisher":"UNIDO, Industrial Development Report 2026 (background report, ch. 5)","year":2025,"authors":["Avenyo","Tregenna","Asiama","Ncube"],"type":"background-paper","programmes":["IND"],"externalUrl":"https://www.unido.org/idr/idr2026","regions":["Africa-wide"],"project":"unido-idr-2026-background"}$rita$::jsonb, 'published'),
('publications', 'the-past-and-the-present-the-nigerian-ebola-experience-and-covid-19', $rita${"title":"The past and the present: the Nigerian Ebola experience and the Covid-19 pandemic","publisher":"INCLUDE Platform","year":null,"authors":["Konte","Ndubuisi","Okafor"],"type":"report","programmes":[],"archive":true,"regions":["West Africa"],"authorOrderConfirmed":true,"externalUrl":"https://includeplatform.net/publications/the-past-and-the-present-the-nigerian-ebola-experience-and-the-covid-19-pandemic-2/","pdf":"https://includeplatform.net/wp-content/uploads/2023/04/The-Past-and-the-Present-The-Nigerian-Ebola-experience-and-the-Covid-19-Pandemic.pdf","summary":"The paper compares Nigeria's success against Ebola with its country-wide response to COVID-19, and assesses which factors may have prevented the country from repeating that success.","keyFindings":["Available statistics show neither a Nigerian win over COVID-19 nor a clear path to one."],"sources":["https://includeplatform.net/publications/the-past-and-the-present-the-nigerian-ebola-experience-and-the-covid-19-pandemic-2/"]}$rita$::jsonb, 'published'),
('publications', 'too-big-to-be-ignored-how-energy-poverty-undermines-productive', $rita${"title":"Too big to be ignored: how energy poverty undermines productive efficiency","publisher":"Energy Policy 181, 113733","year":2023,"authors":["Ndubuisi","Yuni","Urom","Abid"],"type":"journal","programmes":["EN"],"externalUrl":"https://doi.org/10.1016/j.enpol.2023.113733","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1016/j.enpol.2023.113733","pdf":"https://repository.tudelft.nl/file/File_cb160e76-c622-45f7-b736-8775510833c0","summary":"The large literature on the drivers of productive efficiency has not considered energy poverty, even though it affects efficiency on several fronts. This paper finds that energy poverty negatively affects productive efficiency.","keyFindings":["Energy poverty negatively affects productive efficiency.","The negative effect persists across regions and is not sensitive to cross-country differences in income level.","The effect is more pronounced at higher levels of productive efficiency."],"methods":"Data on 100 developing countries, 2000–2017.","sources":["https://research.tudelft.nl/en/publications/too-big-to-be-ignored-how-energy-poverty-undermines-productive-ef","https://ideas.repec.org/a/eee/enepol/v181y2023ics030142152300318x.html"],"note":"Open access."}$rita$::jsonb, 'published'),
('publications', 'trade-exposure-and-social-cohesion-evidence-from-uganda', $rita${"title":"Trade exposure and social cohesion: evidence from Uganda","publisher":"STEG Working Paper 069","year":2023,"authors":["Vrolijk","Ndubuisi"],"type":"working-paper","programmes":["IND"],"regions":["East Africa"],"authorOrderConfirmed":true,"externalUrl":"https://cepr.org/publications/wp069","pdf":"https://steg.cepr.org/sites/default/files/2023-07/WP069%20VrolijkNdubuisiTradeExposureAndSocialCohesion.pdf","summary":"Does trade exposure change social cohesion? Using Uganda's exchange rate liberalisation as a natural experiment, the paper finds significant, though economically small, effects on trust, participation and identity.","keyFindings":["Exposure to exchange rate shocks reduces trust and enhances participation, with ambiguous effects on identity.","The effects run mainly through the expenditure channel (household exposure), and to a lesser extent through earnings (worker and firm exposure)."],"methods":"Micro tax data and a natural experiment (Uganda's exchange rate liberalisation), with firm, worker and household exposure measures.","sources":["https://cepr.org/publications/wp069","https://steg.cepr.org/sites/default/files/2025-04/PB009%20SRG%20368%20Vrolijk%20and%20Ndubuisi.pdf"]}$rita$::jsonb, 'published'),
('publications', 'trade-for-catch-up-how-gvc-participation-affects-productive-efficiency', $rita${"title":"Trade for catch-up: examining how global value chains participation affects productive efficiency","publisher":"Journal of Productivity Analysis 59(2), 195–215","year":2023,"authors":["Ndubuisi","Owusu"],"type":"journal","programmes":["INN"],"externalUrl":"https://link.springer.com/article/10.1007/s11123-023-00663-6","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1007/s11123-023-00663-6","pdf":"https://link.springer.com/article/10.1007/s11123-023-00663-6","summary":"Earlier studies of trade-driven catch-up overlooked global value chain participation as a way to speed up efficiency gains. The paper finds that GVC participation helps technology-lagging countries become more efficient and close the gap to the frontier.","keyFindings":["GVC participation helps technology-lagging countries close the efficiency gap to the global frontier.","Gains are larger with more human capital, deeper financial markets and stable macroeconomic conditions.","Gains are larger for countries specialised in downstream activities."],"methods":"Data envelopment analysis of efficiency relative to the global frontier, regressed on GVC participation with panel fixed effects, difference-GMM, Tobit and fractional response models.","sources":["https://link.springer.com/article/10.1007/s11123-023-00663-6","https://research.tudelft.nl/en/publications/trade-for-catch-up-examining-how-global-value-chains-participatio"]}$rita$::jsonb, 'published'),
('publications', 'trust-and-r-and-d-investment-evidence-from-oecd-countries', $rita${"title":"Trust and R&D investments: evidence from OECD countries","publisher":"Journal of Institutional Economics 16(6), 809–830","year":2020,"authors":["Ndubuisi"],"type":"journal","programmes":["INN"],"regions":["Global"],"authorOrderConfirmed":true,"externalUrl":"https://econpapers.repec.org/article/cupjinsec/v_3a16_3ay_3a2020_3ai_3a6_3ap_3a809-830_5f4.htm","pdf":"https://mpra.ub.uni-muenchen.de/97043/1/MPRA_paper_97043.pdf","summary":"Social trust can increase R&D investment by expanding firms' access to external finance and by reducing relational risks that expose firms to hold-ups or expropriation.","keyFindings":["Industries dependent on external finance have higher R&D intensity in trust-intensive countries.","Industries vulnerable to relational risks also have higher R&D intensity in trust-intensive countries.","Access to external finance and lower relational risk are causal pathways linking trust and R&D."],"methods":"Industry-level data on R&D investment intensity in 20 OECD countries.","sources":["https://www.idos-research.de/en/others-publications/article/trust-and-rd-investments-evidence-from-oecd-countries","https://mpra.ub.uni-muenchen.de/97043/"]}$rita$::jsonb, 'published'),
('publications', 'trust-efficient-contracting-and-export-upgrading', $rita${"title":"Trust, efficient contracting and export upgrading","publisher":"European Journal of Development Research 34(6), 2708–2729","year":2022,"authors":["Ndubuisi","Owusu"],"type":"journal","programmes":["INN"],"regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1057/s41287-021-00486-x","externalUrl":"https://ideas.repec.org/a/pal/eurjdr/v34y2022i6d10.1057_s41287-021-00486-x.html","summary":"Research on contracting institutions and export quality has largely overlooked informal institutions. The paper tests whether trust drives product-quality upgrading by easing contractual frictions, and finds that contract-intensive industries in high-trust countries upgrade more.","keyFindings":["Contract-intensive industries in high-trust societies see a disproportionately larger rise in producing and exporting higher-quality products.","The result holds after controlling for conventional sources of comparative advantage and formal institutions.","Strong informal institutions can support market performance even where formal institutions are weak."],"methods":"Industry-level data for 1995–2014, estimated with a generalised difference-in-differences design.","sources":["https://ideas.repec.org/a/pal/eurjdr/v34y2022i6d10.1057_s41287-021-00486-x.html","https://cris.maastrichtuniversity.nl/en/publications/trust-efficient-contracting-and-export-upgrading/"]}$rita$::jsonb, 'published'),
('publications', 'unesco-science-report-towards-2030-ch-2-tracking-trends-in-innovation', $rita${"title":"Tracking trends in innovation and mobility (UNESCO Science Report: Towards 2030)","publisher":"UNESCO Science Report: Towards 2030, Global Overview","year":2015,"authors":["Avenyo","Chien","Hollanders","Marins","Schaaper","Verspagen"],"type":"book-chapter","programmes":["INN"],"externalUrl":"https://unesdoc.unesco.org/ark:/48223/pf0000235446","regions":["Global"],"authorOrderConfirmed":true,"pdf":"https://uis.unesco.org/sites/default/files/documents/unesco-science-report-towards-2030-part1.pdf","sources":["https://uis.unesco.org/sites/default/files/documents/unesco-science-report-towards-2030-part1.pdf","https://www.um.edu.mt/library/oar/handle/123456789/108693"]}$rita$::jsonb, 'published'),
('publications', 'wage-effects-of-gvc-participation-and-position', $rita${"title":"Wage effects of global value chains participation and position: an industry-level analysis","publisher":"Journal of International Trade & Economic Development 31(7), 1086–1107","year":2022,"authors":["Ndubuisi","Owusu"],"type":"journal","programmes":["INN"],"externalUrl":"https://www.tandfonline.com/doi/full/10.1080/09638199.2022.2058068","regions":["Global"],"authorOrderConfirmed":true,"doi":"10.1080/09638199.2022.2058068","pdf":"https://merit.unu.edu/publications/working-papers/abstract/?id=9097","summary":"The paper studies how participation and position in global value chains (GVCs) affect wages, comparing developed and developing countries and different labour market regulations.","keyFindings":["In developed countries, GVC participation and upstream specialisation are both associated with higher wages.","In developing countries, participation is linked to higher wages, but upstream specialisation puts downward pressure on them.","In developing countries, participation mainly benefits higher earners; the positive wage effect appears only under stringent labour market regulation."],"methods":"Industry-level analysis across developed and developing countries (earlier version: UNU-MERIT Working Paper 2021-042).","sources":["https://merit.unu.edu/publications/working-papers/abstract/?id=9097","https://ideas.repec.org/a/taf/jitecd/v31y2022i7p1086-1107.html"]}$rita$::jsonb, 'published')
